import Foundation

private typealias E = EvidenceSeed

/// Alternate tellings, batch K: the same cases, played out another way.
extension StoryVariants {
    static let variantsK: [CaseTemplate] = [moonshineRunCrashV1, wrongHouseShotV1, nursingHomeNightShiftV1, kittenFoodBurglarsV1, grandchildCallerSchemeV1, bakeryInsuranceBlazeV1, fentanylSalineSwapV1, clinicWithoutLicenseV1, fakeIllnessFundraiserV1, golfPartnerTipsV1, mowerOnTheBypassV1, buriedCoinDigV1, harborMonsterHoaxV1, cheeseTruckTheftV1, goatInTheSanctuaryV1, gardenGnomeHeistV1, creamPieSmashV1, mascotNappingCaseV1, giantPumpkinSmashV1, spotlightHuntV1, electionSignSabotageV1, oysterBedPoachV1, rodeoClownShoveV1, plowChaseLotV1, pranksterBalloonCallV1]

    static let moonshineRunCrashV1 = SmallCases.make(
        key: "story.moonshineRunCrash",
        category: .traffic,
        headlines: ["Pickup Full of Mason Jars Flees Checkpoint at Dawn", "Chase Ends With a Truck in a Creek Bed"],
        law: "fleeing",
        threshold: 6,
        spec: "Operated a motor vehicle on a street while fleeing a law enforcement officer, on or about {DATE}.",
        ages: 18...65,
        victim: false,
        summary: "A deputy flagged down a pickup at a gravel road checkpoint at dawn on {DATE}. {D} drove around the cones and raced off, ending in a creek bed with clear jars spilled across the bed. {DL} says fog hid an unmarked SUV and {D.he} never knew it was police.",
        state: [E(.video, 3, "Body Camera", "The deputy waves a flashlight and the pickup swerves past."), E(.digital, 3, "Plate Reader", "A hit on the pickup five minutes before the chase."), E(.document, 2, "Crash Photos", "Jars of clear liquor in a creek bed.")],
        defense: [E(.document, 1, "Weather Log", "Dense fog recorded that morning.")],
        role: "Deputy",
        exam: [.direct("Where were you posted that morning, and why?", "\"I was working a gravel road checkpoint at dawn on a tip about liquor hauling. I stood near the cones with a flashlight and my unmarked SUV.\""), .direct("What did you do when the pickup approached?", "\"I stepped out into the lane, waved the flashlight side to side, and signaled for the driver to stop. I stood where I could be seen.\""), .direct("How did the driver respond?", "\"The pickup slowed for a second, swerved around the cones, then sped up and went past me close enough that I stepped back.\""), .direct("What did your plate reader show?", "\"A hit on that same pickup about five minutes before the chase, on a road leading toward the checkpoint. It matched a vehicle we had been watching.\""), .direct("What did you do after the pickup passed?", "\"I got in the SUV, turned on the lights and siren, and followed it down the gravel road until it left the road.\""), .direct("What did you find at the creek?", "\"The pickup was nosed down in a creek bed, and clear jars of liquor were spilled across the bed. The driver was shaken but standing.\""), .cross("How thick was the fog that morning?", "\"Heavy, I admit. Visibility along that stretch was short, and I would not call it a clear dawn.\""), .cross("Was your SUV marked as a patrol vehicle?", "\"It was unmarked, with a small light bar. I do not have a decal on the doors or a roof bar like a cruiser.\""), .cross("Was the light bar on when the pickup arrived?", "\"I believe it was flashing, but I cannot swear a driver in that fog saw it from any distance.\""), .cross("When did you turn on the siren?", "\"After the pickup passed me. I did not have it on while I stood in the road, so the driver had no sound to hear.\""), .cross("Did you see {D}'s face before the pickup swerved?", "\"Only through a windshield for a moment. I could not read what {D} saw or understood in that instant.\"")],
        defenseRole: "Neighbor",
        defenseExam: [.direct("What was the weather like that morning?", "\"Thick fog. I could not see my own mailbox from my porch, and it stayed that way well after sunrise.\""), .direct("Where do you live in relation to the gravel road?", "\"My house sits about two hundred yards off it. I hear everything that passes, so I was paying attention that morning.\""), .direct("Did you hear a siren before the pickup went by?", "\"Not until a little later. First I heard an engine go past fast, and a siren came on behind it afterward.\""), .direct("Could you see the checkpoint from your yard?", "\"No. In that fog I could see shapes and a light, but nothing I could have called a police vehicle.\""), .direct("Have you seen unmarked vehicles on that road before?", "\"Now and then. Usually they sit with the lights off, and people on this road know to be careful of speeders.\""), .direct("How did the pickup sound as it passed?", "\"Loud, like the driver was in a hurry, but not out of control until near the creek. Then I heard a crash.\""), .cross("Did you see {D}'s pickup at the cones?", "\"No. I was inside my house, so I only heard what happened and could not see the checkpoint.\""), .cross("Did you see a light bar on the SUV?", "\"I did not. I saw nothing at all through the fog, and I cannot say what was on that SUV.\""), .cross("Are you friends with {D}?", "\"I know the family from the road. I would tell you the same thing about anyone who drove past that morning.\""), .cross("Did you go out to the creek?", "\"I walked down once I heard the crash. By then deputies were there, and I stayed back out of the way.\""), .cross("Did you see the jars?", "\"Yes, I saw jars lying in the creek bed. I do not know what was in them or whose they were.\"")],
        theory: ("{D} ran from a marked stop with a load of liquor.", "Fog hid the police."),
        allocution: "\"I should have stopped.\"",
        truths: ("{DL} slowed at a driveway, saw the light bar clearly, then floored it.", "The light bar was caked in mud and the siren came on only after {DL} had passed."),
        defendant: [.direct("What were you doing on the gravel road that morning?", "\"I was hauling jars for a cousin to a buyer, and I had left before dawn to avoid the fog turning worse.\""), .direct("What did you see ahead of you in the fog?", "\"A light waving in the mist, and a dark shape beside it. I could not tell what it was, and it spooked me.\""), .direct("Why did you drive around the cones?", "\"I thought someone was setting up a robbery on a lonely road, and I did not want to stop and find out.\""), .direct("What did you know about the jars you were hauling?", "\"They were clear jars my cousin loaded and asked me to drop off. I did not ask what was in them.\""), .direct("What happened as you left the checkpoint?", "\"I sped up, the road bent, and the truck slid on the wet gravel. I lost control and ended in the creek.\""), .direct("What do you want the jury to understand?", "\"I did not know it was police. I was frightened, I drove badly, and I am sorry for the damage.\""), .cross("You saw a light bar on that SUV, didn't you?", "\"I saw a light in the fog. I did not know it was a police light bar until later, honestly.\""), .cross("You steered around the cones, didn't you?", "\"Yes. I went around them because I was scared, and I would have done it for any strange vehicle.\""), .cross("You knew you were hauling jars of liquor, didn't you?", "\"I knew it was jars my cousin gave me. I suspected it was moonshine, but I did not look.\""), .cross("You never pulled over, even after the siren came on, did you?", "\"I lost control right around then, so I did not have the chance. I was still going too fast.\""), .cross("A plate reader hit your truck five minutes earlier. Where were you headed?", "\"Toward a buyer my cousin named. I had not been to that spot before, and I was following directions.\"")],
        openings: ("A deputy waved a flashlight at a gravel road checkpoint at dawn, and {D}'s pickup swerved around the cones and sped away, ending in a creek bed with jars of clear liquor spilled across the bed.", "Fog covered the road that morning, the SUV was unmarked, and the siren came on only after {D} passed. {D} thought a robbery was coming and ran, which is fear and not a crime."),
        closings: ("The deputy stood in the road with a light, the plate reader had the truck minutes earlier, and {D} went around the cones and floored it. Fog does not erase what a driver saw.", "A foggy morning, a muddy unmarked SUV, a late siren, and a frightened driver who lost control. The State must prove {D} knew who stood in that road."),
        timeline: [(0, "5:50 a.m.: the checkpoint."), (0, "5:52 a.m.: the pickup speeds off."), (0, "6:05 a.m.: the creek."), (10, "Charges.")],
        identified: "A body camera and a plate reader.",
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let wrongHouseShotV1 = SmallCases.make(
        key: "story.wrongHouseShot",
        category: .violent,
        headlines: ["Carport Shooting Wounds a Neighbor Looking for a Lost Dog", "Homeowner Fired at a Shadow in the Dark"],
        law: "awdwisi",
        threshold: 7,
        spec: "Assaulted {V} with a deadly weapon inflicting serious injury, on or about {DATE}.",
        ages: 25...75,
        victim: true,
        summary: "{V} stepped into {D}'s open carport near midnight on {DATE} calling for a lost dog. {D} fired from a bedroom window and {V} was hit in the thigh. {DL} says a prowler had been working the street and {D.he} saw only a shape.",
        state: [E(.forensic, 3, "Trauma Report", "A thigh wound from a single round."), E(.digital, 3, "Neighbor's 911 Call", "A neighbor reports a person calling for a dog near the carport minutes before the shot."), E(.forensic, 2, "Scene Diagram", "Shot fired from a window 40 feet away.")],
        defense: [E(.document, 1, "Police Reports", "Four prowler reports on the street that month.")],
        role: "Detective",
        exam: [.direct("What call came in that night?", "\"A neighbor called 911 saying someone was walking near a carport calling out a dog's name, a few minutes before a gunshot was reported.\""), .direct("What did you find when you arrived?", "\"{V} was down in the carport with a wound to the thigh from one round. {V} was conscious and told us about the lost dog.\""), .direct("Where was the shot fired from?", "\"From a second floor bedroom window about 40 feet from the carport, based on the shell and the scene diagram we drew.\""), .direct("What does the trauma report say?", "\"A single round struck the thigh, with no exit wound and no damage to major arteries. {V} survived and was treated.\""), .direct("What did {D} tell you?", "\"That {D} saw a shape in the carport, thought of a prowler, and fired once from the window without going outside first.\""), .direct("What was the lighting like in the carport?", "\"Dim. The porch light over the carport was burned out, so the only light was a streetlamp down the block.\""), .cross("Were there prowler reports in that neighborhood?", "\"Yes, four in recent weeks. Neighbors were jumpy, and I took each of those reports myself.\""), .cross("Did {D} report a prowler at that carport before?", "\"{D} told us about seeing someone near the carport days earlier. I did not find a report filed at the time.\""), .cross("Was {V} calling out clearly, as far as you know?", "\"A neighbor heard a dog's name being called. I cannot say how loud it was from the second floor.\""), .cross("Did {D} shout a warning?", "\"{D} says so. Nobody else heard a warning, and {V} says there was none.\""), .cross("Did {D} cooperate with you?", "\"Fully. {D} handed over the firearm, answered questions, and stayed at the scene until we finished.\"")],
        defenseRole: "Neighbor",
        defenseExam: [.direct("What were things like on your street that month?", "\"Everyone was on edge. We had four prowler reports, and people were locking doors they never used to bother with.\""), .direct("Did you see anything near {D}'s carport before that night?", "\"A few nights earlier I saw a figure standing in that carport, and I told {D} about it the next morning.\""), .direct("How was the carport lit that night?", "\"It was dark. The light over it had burned out weeks ago, and {D} had not replaced it yet.\""), .direct("Did you hear the gunshot?", "\"Yes. One shot, sharp, about midnight. I looked out and saw {D}'s window and a shape in the carport.\""), .direct("What did you do next?", "\"I called 911 and went out when I heard someone calling for help. {V} was on the ground in the carport.\""), .direct("How did {D} react afterward?", "\"{D} came out in a panic, kneeling beside {V} and saying over and over that {D.he} thought it was a prowler.\""), .cross("Did you hear anyone yell a warning before the shot?", "\"No. I heard nothing before the shot, and that is the truth, even though I wish I had heard something.\""), .cross("Did you hear someone calling a dog's name?", "\"Yes, I did, once or twice. It was before the shot, and I did not think anything of it then.\""), .cross("Did anyone tell you the dog was lost?", "\"Not until afterward. I know the dog now, a small brown one that lives a few doors down.\""), .cross("Did {D} ever own a gun before that month?", "\"Yes. {D} has kept one in a bedroom for years, as far as I know.\""), .cross("Are you close to {D}?", "\"We are neighbors and friendly. I am telling you what I saw, and I would say it about anyone.\"")],
        theory: ("{D} fired at a harmless neighbor without looking.", "A frightened homeowner in the dark."),
        allocution: "\"I should have called first.\"",
        truths: ("{DL} heard the dog name called out and fired anyway.", "The carport had no light and {DL} had just seen a prowler there days earlier."),
        defendant: [.direct("What did you see that night?", "\"A shape moving in my carport near midnight, with no light and nothing on to tell me who it was.\""), .direct("Why were you on edge?", "\"Four prowlers had worked our street, and I had seen someone in my carport days earlier. I was frightened for my home.\""), .direct("Did you hear anything from outside?", "\"I heard noise, but I did not make out words. I may have missed a dog's name over the wind and my pulse.\""), .direct("Did you warn the person?", "\"I shouted from the window that I had a gun and to get out. I did not hear an answer.\""), .direct("Why did you fire from the window?", "\"I thought the shape was coming toward my house. I was afraid and fired once before I really thought.\""), .direct("What did you do immediately after?", "\"I ran outside, saw {V} on the ground, called for help, and applied pressure to the wound until paramedics came.\""), .cross("You never went outside before firing, did you?", "\"No. I did not. I wish I had, because I would have seen it was someone looking for a dog.\""), .cross("You could not see a weapon on that shape, could you?", "\"No. I saw only a shape. I did not see a weapon or anything in a hand.\""), .cross("A neighbor heard a dog's name being called, didn't they?", "\"So they say. I did not hear it clearly, and I do not think I heard it at all.\""), .cross("You were forty feet away at a second floor window, weren't you?", "\"Yes. It was dark, and I was upstairs. I should have called the police instead of firing.\""), .cross("You fired at a person who was not coming at you, didn't you?", "\"I believed {V} was coming closer. Looking back, I cannot say that is what {V} was doing.\"")],
        openings: ("Near midnight {V} stepped into {D}'s open carport calling for a lost dog, and {D} fired from a bedroom window forty feet away, hitting {V} in the thigh without ever going outside to look.", "Four prowlers had worked this street and the carport light was dead. {D} saw a shape in the dark and fired out of fear. A scared homeowner's mistake is not a crime of hate."),
        closings: ("A neighbor heard a dog being called, nobody heard a warning, and {D} fired from forty feet at a shape without looking outside. {V} was a stranger with a leash and a worry.", "A dark carport, four prowler reports, and a shape in the night. {D} fired in fear, and the State has not shown a homeowner who wanted to hurt anyone."),
        timeline: [(-30, "Prowler reports begin."), (0, "11:50 p.m.: {V} enters the carport."), (0, "11:51 p.m.: the shot."), (1, "Detectives interview {D}.")],
        identified: "A 911 call.",
        mood: .divided,
        doctrines: ["selfDefense"])

    static let nursingHomeNightShiftV1 = SmallCases.make(
        key: "story.nursingHomeNightShift",
        category: .violent,
        headlines: ["Assisted Living Aide Skipped Rounds as Resident Lay on the Floor", "Family Finds Bruises and Missed Medication"],
        law: "patientNeglect",
        threshold: 7,
        spec: "Having charge of a patient, willfully or recklessly failed to provide care, on or about {DATE}.",
        ages: 20...60,
        victim: true,
        summary: "{V}, a resident of an assisted living wing, fell beside the bed on {DATE} and lay there for hours. {D} was assigned to the wing for the evening. {DL} says a second aide called out and covered rounds that never got logged.",
        state: [E(.digital, 3, "Pendant Alerts", "Fall alarm active for three hours."), E(.document, 3, "Medication Sheet", "Evening doses unsigned."), E(.video, 2, "Hall Camera", "{D} at the nurse desk most of the shift.")],
        defense: [E(.document, 1, "Call Sheet", "A second aide called out sick.")],
        role: "Facility inspector",
        exam: [.direct("What did you inspect at the assisted living facility?", "\"The fall of {V}, a resident who lay beside the bed for hours on the date in question. I reviewed alerts, charts, schedules, and cameras.\""), .direct("What did the pendant alert record show?", "\"A fall alarm active for three hours that was never acknowledged. The panel log shows the alarm firing and then no response.\""), .direct("What did the medication sheet show?", "\"Evening doses were unsigned for the wing. Nothing was initialed for {V} that night, and the sheet was blank where it should have been checked.\""), .direct("What did the hall camera show?", "\"{D} at the nurse desk for most of the shift, with only a few short trips down the hall.\""), .direct("What was the staffing that night?", "\"One aide short on the wing. The schedule had two aides, but only {D} was physically assigned and present.\""), .direct("Was a supervisor reachable?", "\"By phone, yes. The on-call line shows a couple of calls from the wing during the evening, which I noted.\""), .cross("Did the panel get muted or turned down?", "\"The panel log shows the volume lowered during the shift. I cannot tell from the log who did that.\""), .cross("Were there other residents who needed help?", "\"Yes, several on that wing. The call volume that evening was well above a normal night.\""), .cross("Did the facility have a policy for short staffing?", "\"It does. A short shift should be escalated to a supervisor, and the on-call log shows {D} tried.\""), .cross("Did {D} document rounds?", "\"Not that night. The round sheet is blank, though I cannot say whether rounds were done and not logged.\""), .cross("Was {V} found by {D}?", "\"No. {V} was found by the morning shift, and {D} says {D.he} did not learn of the fall until then.\"")],
        defenseRole: "Dietary worker",
        defenseExam: [.direct("What is your job at the facility?", "\"I work in the kitchen and dietary department. I serve meals and clean the dining area, and I am usually off the wing.\""), .direct("Who was on the wing that evening?", "\"As far as I saw, only {D}. The second aide had been called off earlier that day, I heard.\""), .direct("Did you hear any alarm that night?", "\"No. The kitchen is on another floor, and the pendant panel is not something I can hear from there.\""), .direct("How did {D} seem that evening?", "\"Hurried. {D} was walking fast between rooms, answering buzzers, and looked worn out when I brought a snack tray around.\""), .direct("Did you see {D} ask anyone for help?", "\"I saw {D} on the desk phone more than once, talking low, and then hanging up looking frustrated.\""), .direct("What was the mood on staffing that week?", "\"Tense. We were short in the kitchen too, and aides kept saying they had too many residents for one person.\""), .cross("Did you see {D} mute the pendant panel?", "\"No. I was never near the panel that night, so I cannot say who touched it.\""), .cross("Did you hear what {D} said on the phone?", "\"Not the words. I only saw {D} talking and hanging up, and I assumed it was about staffing.\""), .cross("Were you on the wing at the time of the fall?", "\"No. I only walked through briefly with trays. I cannot say what happened in {V}'s room.\""), .cross("Did you tell anyone about the staffing problem?", "\"I mentioned it to my own supervisor, but I do not know if that went anywhere.\""), .cross("Do you like {D}?", "\"I do. {D} is kind to residents, and I would say so, but that is not what I am here to tell you.\"")],
        theory: ("{D} left a fallen resident alone for hours.", "One aide doing the work of two."),
        allocution: "\"I let it slip.\"",
        truths: ("{DL} muted the pendant panel to stop the beeping.", "{DL} had asked a supervisor for help twice and was refused."),
        defendant: [.direct("How many residents did you cover that evening?", "\"The whole wing, around a dozen rooms, because the second aide had been called off and no replacement came.\""), .direct("Why was the medication sheet blank?", "\"I was running behind. I meant to sign it after I finished the last doses, and then I got pulled away by calls.\""), .direct("Did you ask for help?", "\"Yes, twice by phone. I called the on-call supervisor and asked for another aide, and I was told no one was available.\""), .direct("Why was the panel muted?", "\"It had been glitching and beeping all week with false alarms. I turned the volume down to hear residents, which was wrong.\""), .direct("When did you learn about {V}'s fall?", "\"The next morning, when the day shift told me. I felt sick, because I never heard any alarm go off.\""), .direct("What would you do differently?", "\"I would refuse the shift alone and put it in writing. I did what I thought I could and it was not enough.\""), .cross("Did you mute the pendant panel?", "\"I lowered the volume because of the glitching. I did not mean to ignore a fall, and I did not know about one.\""), .cross("The alarm was active for three hours, wasn't it?", "\"That is what the log says. I did not hear it, and I accept that the panel did not alert me.\""), .cross("You spent most of the shift at the nurse desk, didn't you?", "\"I was there between rooms, charting and answering calls. I did walk the hall, though I did not log every round.\""), .cross("You never initialed the evening medication sheet, did you?", "\"No, I did not. I was behind and meant to fill it in later, and I should have done it as I went.\""), .cross("How do we know you asked a supervisor for help?", "\"The on-call phone log shows the calls. I can show them, and they back up what I told you.\"")],
        openings: ("{V}, an assisted living resident, fell beside the bed and lay there for three hours while a fall alarm went unanswered. {D} was the only aide on the wing, with a blank medication sheet and a muted panel.", "{D} asked a supervisor for help twice and was told no one was available. One aide alone on a dozen rooms is a staffing failure, not an aide who ignored an alarm."),
        closings: ("A fall alarm active for three hours, an unsigned medication sheet, a panel turned down, and an aide at the desk. {V} lay on the floor because no one answered.", "{D} called for help, was refused, and kept going alone on a glitchy panel. The State has a bad night in an understaffed wing and no proof {D} knew about a fall."),
        timeline: [(0, "4 p.m.: shift begins."), (0, "8 p.m.: the fall."), (0, "11 p.m.: {V} found."), (5, "Inspector visits.")],
        identified: "Pendant alert records.",
        mood: .sympathetic,
        doctrines: ["burdenOfProof"])

    static let kittenFoodBurglarsV1 = SmallCases.make(
        key: "story.kittenFoodBurglars",
        category: .property,
        headlines: ["Dog Walker Hit Seven Homes While Owners Were at the Beach", "Spare Key Lockbox Opens for Thief"],
        law: "felonyLarceny",
        threshold: 7,
        spec: "Took and carried away property of {V} worth over $1,000, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} walked dogs for clients and held lockbox codes to seven homes. During {V}'s beach week starting {DATE}, a coin collection and a watch worth about $4,000 vanished. {DL} says a roommate had the same codes.",
        state: [E(.digital, 3, "Lockbox Log", "Codes entered by {D}'s account."), E(.document, 3, "Pawn Ticket", "A coin collection sold under {D}'s phone number."), E(.video, 2, "Camera Clip", "{D} leaving with a bag.")],
        defense: [E(.statement, 1, "Roommate Texts", "Texts show the roommate asking for the codes.")],
        role: "Homeowner",
        exam: [.direct("How do you know {DL}?", "\"{D} walked my dogs for about a year and held the lockbox codes to my house, along with six other clients' homes.\""), .direct("What did you find when you came home from your beach week?", "\"A coin collection I had kept for decades and a watch worth about $4,000 were both gone from the study, and nothing else was disturbed.\""), .direct("What does the lockbox log show?", "\"Every entry code used during my week away came from {D}'s account. The log lists dates and times, and they match the days I was away.\""), .direct("Where did the coins end up?", "\"A pawn ticket shows the whole collection sold across a counter, and the phone number on the ticket is {D}'s.\""), .direct("What does the camera clip show?", "\"{D} walking out of my front door carrying a bag that looks heavier than a leash and treats would be.\""), .direct("How much were the items worth to you?", "\"The watch alone was about $4,000, and the coins were a lifetime of collecting that I can never fully replace.\""), .cross("Did you ever give your codes to anyone besides {DL}?", "\"I gave one code to the service, and I assumed only {D} had it. I never gave it to a roommate.\""), .cross("Did you know {DL} lived with someone?", "\"I had heard {D} had a roommate, but I never met that person or discussed my house with anyone but {D}.\""), .cross("Can you tell from the clip what is in the bag?", "\"No. The bag is closed. I only know my things were missing and the walk-out matches the timing.\""), .cross("Was anything else taken from the house?", "\"No, which is strange for a burglary. Only the coins and the watch were gone, and those were easy to carry.\""), .cross("Did {DL} ever act dishonestly before this?", "\"Not that I saw. {D} was punctual, and the dogs were always happy. That is why this hurts.\"")],
        defenseRole: "Roommate",
        defenseExam: [.direct("How do you know {DL}?", "\"We share an apartment and have for two years. We both do some dog walking and pet sitting.\""), .direct("Did you ask {DL} for lockbox codes?", "\"Yes, I texted asking for several. I wanted to cover some visits while {D} was out of town.\""), .direct("Why did you want them?", "\"We had agreed to split jobs that week. I needed the codes to get in and handle the dogs.\""), .direct("Did {DL} send them?", "\"I do not think so. {D} said to wait until later, and I let it go.\""), .direct("Did you ever go into the homeowner's house?", "\"No. I had no code of my own, so I could not have entered through the lockbox.\""), .direct("Did you pawn any coins?", "\"Never. I have not been in a pawn shop in years.\""), .cross("You tried to get the codes, didn't you?", "\"I asked. That is in the texts. Asking is not the same as using them.\""), .cross("You live with {DL} and could borrow a phone, couldn't you?", "\"I suppose I could, but I did not. I have my own phone and my own number.\""), .cross("Did {DL} ever keep the codes written somewhere you could see?", "\"There was a notebook on the counter. I did not copy from it.\""), .cross("Were you home the nights {DL} was out?", "\"Sometimes. I do not keep a log of where I was every night.\""), .cross("Did {DL} have money problems?", "\"We both watch our budgets. I never saw anything that suggested desperation.\"")],
        theory: ("{D} used lockbox codes to steal.", "A roommate had the codes."),
        allocution: "\"I made a bad choice.\"",
        truths: ("{DL} was the only one logged into the lockbox on every theft date.", "The roommate pawned nothing but did text asking for the codes."),
        defendant: [.direct("What was your job for {V}?", "\"I walked and fed the dogs twice a day. I had the lockbox code so I could get in while {V} was away.\""), .direct("Did you enter the house during the beach week?", "\"Yes, twice a day for the dogs, so my code shows up. That is the whole reason the log has my name.\""), .direct("Did anyone else know the codes?", "\"My roommate did. We keep them on a shared sheet because we split clients when one of us is sick.\""), .direct("Did you sell any coins?", "\"No. I never went to a pawn shop. I do not know how my phone number ended up on a ticket.\""), .direct("What about the clip of you leaving with a bag?", "\"That was my dog kit, with leashes, bags, and treats. I carry it into every house I visit.\""), .direct("How do you feel about being accused?", "\"Awful. I take pride in being trusted with keys, and now I might lose every client I have.\""), .cross("Your code was used on every theft date, wasn't it?", "\"It was used because I was there for the dogs, but yes, it is logged on those days.\""), .cross("Your phone number was on the pawn ticket, wasn't it?", "\"That is what the ticket says. I did not write it, and I cannot explain it.\""), .cross("You carried a bag out of that house, didn't you?", "\"I carried my dog kit. I understand the clip cannot prove what was in it.\""), .cross("Your roommate texted asking for codes, didn't {D.he}?", "\"I understand there were texts. I did not hand over any codes in response.\""), .cross("You are the only one the lockbox log names, aren't you?", "\"The log only records which code was punched in. It does not say who was holding it.\"")],
        openings: ("A dog walker held lockbox codes to seven homes. During a beach week a coin collection and a $4,000 watch vanished, the log shows only {D}'s code used, and a pawn ticket carries {D}'s phone number. The State will show the log and the clip.", "Dog walkers share codes, and a roommate texted asking for them. {D} says the log only proves a code was punched in, not whose hand was on the keypad, and a roommate will explain the texts."),
        closings: ("Only {D}'s code opened that door during the beach week, a pawn ticket carries {D}'s phone number, and a clip shows {D} leaving with a bag. The trail ends at {D}.", "A log records codes, not hands. A roommate asked for them and a ticket carries only a number. The State has not proved {D} took anything from that study."),
        timeline: [(-60, "Walker hired."), (0, "{V} leaves for the beach."), (7, "Missing items found."), (25, "Pawn match.")],
        identified: "A lockbox log.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let grandchildCallerSchemeV1 = SmallCases.make(
        key: "story.grandchildCallerScheme",
        category: .whiteCollar,
        headlines: ["Rideshare Driver Collected Cash for a 'Lawyer' in Elder Scam", "Seniors Told a Grandchild Had Crashed a Car"],
        law: "exploitationElder",
        threshold: 8,
        spec: "Knowingly obtained the funds of {V}, an older adult, through deception, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Seven seniors were told by phone that a grandchild had crashed a car and needed money for a lawyer. A driver in a gray sedan collected the cash, including $9,500 from {V} on {DATE}. {DL} says {D.he} only accepted delivery jobs through an app and never spoke to a victim.",
        state: [E(.video, 3, "Porch Camera", "A gray sedan and {D} taking an envelope."), E(.digital, 3, "App Records", "Seven pickup jobs on {D}'s account."), E(.document, 2, "Deposit Slips", "Cash deposited into a prepaid card account.")],
        defense: [E(.digital, 1, "Delivery App Chat", "The app dispatcher called the jobs 'document runs'.")],
        role: "Detective",
        exam: [.direct("How did the scheme work?", "\"Seniors got calls saying a grandchild had crashed a car and needed money for a lawyer. A driver in a gray sedan then collected cash at the door.\""), .direct("How many victims were there?", "\"Seven seniors. The largest single loss we found was $9,500, taken from {V} on {DATE}.\""), .direct("What does the porch camera show?", "\"A gray sedan at the curb and {D} walking up and taking an envelope from the victim's hand.\""), .direct("What do the app records show?", "\"Seven pickup jobs on {D}'s delivery account, each matching one of the seven victims and their addresses.\""), .direct("Where did the cash go?", "\"Deposit slips show cash going into a prepaid card account within hours of each pickup.\""), .direct("What did {DL} tell you?", "\"That the jobs came through a delivery app as document runs, and that {D} never spoke with any victim.\""), .cross("Did you see {DL} speak with any victim about a grandchild?", "\"No. The porch camera has no audio of a script, and no victim said {D} mentioned a car crash.\""), .cross("Did anyone tell {DL} the envelopes held cash?", "\"I found no message saying so. The app notes called them document runs.\""), .cross("Was {DL}'s own name on the app account?", "\"Yes. The account was in {D}'s name, which is how we traced every pickup.\""), .cross("Did {DL} try to hide from the porch camera?", "\"No. {D} walked right up and looked at the door without covering anything.\""), .cross("Who called the victims?", "\"We have not identified the callers. That part of the scheme remains unsolved.\"")],
        defenseRole: "Victim's daughter",
        defenseExam: [.direct("How are you connected to this case?", "\"One of the victims is my parent. I helped sort out what happened after the call came in.\""), .direct("What did your parent tell you?", "\"That a caller claimed to be a grandchild in trouble. The caller sounded rushed and told them to hand over an envelope.\""), .direct("Who came to the door?", "\"A driver in a gray sedan. My parent said the driver was polite and said very little.\""), .direct("Did the driver mention what was inside?", "\"The driver said something about papers. I do not recall anything about cash.\""), .direct("Did your parent hand over the money willingly?", "\"Yes, out of fear for the grandchild. The caller made it sound urgent.\""), .direct("How is your parent now?", "\"Embarrassed and shaken. It was a lot of money, and the fear was real.\""), .cross("Did the driver know the envelope held cash?", "\"I cannot say. I only saw the driver for a moment.\""), .cross("Did your parent describe the driver clearly?", "\"Only as someone in a sedan. I could not identify anyone from that.\""), .cross("Was the driver on the phone with the caller?", "\"Not that my parent saw.\""), .cross("Did the driver ask for the exact amount?", "\"No. The caller had given that to my parent.\""), .cross("Would a courier normally take an envelope this thick?", "\"I do not know. I have never ordered a courier.\"")],
        theory: ("{D} was the scam's cash collector.", "A delivery driver kept in the dark."),
        allocution: "\"I should have asked more.\"",
        truths: ("{DL} was told to say the envelope held legal papers.", "The app's job notes said nothing about cash."),
        defendant: [.direct("What work were you doing that day?", "\"Delivery jobs through an app. I took pickups for documents and dropped them at an address the app gave me.\""), .direct("Who told you what was in the envelopes?", "\"The dispatcher said they held legal papers. I never opened one. Why would I open someone's legal papers?\""), .direct("Did you speak with any of the seniors?", "\"Only to say I was there for a pickup. I never mentioned a grandchild, a car crash, or a lawyer.\""), .direct("Where did the envelopes go?", "\"To an address the app named. I handed them over and the app paid me a flat fee for each run.\""), .direct("Did the app mention cash?", "\"No. The job notes said document run. If I had seen cash in them I would have refused.\""), .direct("How do you feel now?", "\"Sick. Those people were scared and robbed, and I was the one who showed up at their doors.\""), .cross("Seven pickups in a short time is a lot of legal papers, isn't it?", "\"It was busy, but the app was busy. I took jobs as they came and did not count.\""), .cross("The envelopes felt thick, didn't they?", "\"I did not weigh them. Some were thick, and I assumed contracts could be thick.\""), .cross("You took an envelope from a frightened senior, didn't you?", "\"I took what was handed to me. I did not notice the person was upset.\""), .cross("Cash went to a prepaid card, didn't it?", "\"I understand that. It was not my account, and I never touched that card.\""), .cross("You never asked what the seniors were paying for, did you?", "\"No, and In hindsight, yes. I was told it was legal papers and I left it there.\"")],
        openings: ("Seven seniors were told a grandchild had wrecked a car and needed lawyer money, and a driver in a gray sedan collected cash from each, including $9,500 from {V}. The State will show the porch video, the app records, and the deposits.", "A delivery app called these jobs document runs. {D} says that is all anyone told {D.him}, and a victim's family member will tell you the driver only talked about papers."),
        closings: ("Seven pickups on {D}'s account, a gray sedan on the porch camera, and cash sent to a prepaid card. {D} collected from frightened seniors.", "The app called them document runs and the notes said nothing about cash. The State has not proved {D} knew what the envelopes held."),
        timeline: [(-10, "Calls begin."), (0, "{V} hands over $9,500."), (4, "Seventh pickup."), (9, "Arrest.")],
        identified: "A porch camera.",
        aggravating: ["The victim was particularly vulnerable", "The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let bakeryInsuranceBlazeV1 = SmallCases.make(
        key: "story.bakeryInsuranceBlaze",
        category: .property,
        headlines: ["Furniture Store Fire Traced to Rags Soaked in Solvent", "Owner Sold Stock Weeks Before Blaze"],
        law: "burningBuildings",
        threshold: 8,
        spec: "Willfully and wantonly burned a building, on or about {DATE}.",
        ages: 25...70,
        victim: false,
        summary: "A furniture store owned by {D} burned in the early hours of {DATE}. Solvent-soaked rags were found in the back room. {DL} says the rags caught fire on their own after finishing work.",
        state: [E(.forensic, 3, "Fire Investigator Report", "Accelerant in the back room."), E(.document, 3, "Bank Letters", "A line of credit called in."), E(.digital, 2, "Sales Records", "Stock sold at a steep discount the week before.")],
        defense: [E(.document, 1, "Refinish Invoice", "Refinishing work done the day before the fire.")],
        role: "Fire investigator",
        exam: [.direct("What did you find at the furniture store after the fire?", "\"A burned back room with the worst damage near a pile of rags. The burn pattern showed the fire started low, near the floor.\""), .direct("What did lab testing show?", "\"Accelerant residue in the back room. That fits solvent, and the rags were soaked with it.\""), .direct("What did you learn about the store's finances?", "\"The bank had called in a line of credit shortly before the fire, which put {D} under heavy pressure.\""), .direct("What do the sales records show?", "\"Stock was sold at a steep discount the week before. Normal sales did not move that way.\""), .direct("What about the alarm panel?", "\"The panel was turned off the night of the fire. That is documented in the panel's own log.\""), .direct("Where was the best stock?", "\"Moved to a storage unit before the fire. That was left out of what burned.\""), .cross("Did you see anyone start the fire?", "\"No. I examined the scene afterward. I did not see who or what ignited it.\""), .cross("Can solvent rags burn without a spark?", "\"Yes, in the right conditions they can heat and ignite on their own. I considered that.\""), .cross("Did you find a device or a timer?", "\"No. I found no device. My opinion rests on the pattern and the accelerant.\""), .cross("Was the alarm off because of service?", "\"I do not know the reason. I know only that it was off in the panel log.\""), .cross("Is moving stock before a sale illegal?", "\"No. Businesses do it for many reasons. It matters alongside the other facts.\"")],
        defenseRole: "Refinishing worker",
        defenseExam: [.direct("What work did you do at the store?", "\"I refinished furniture. I stripped old finishes and applied new ones in the back room.\""), .direct("What did you do the day before the fire?", "\"I finished a dresser and cleaned up. The invoice shows the work was completed that day.\""), .direct("What did you do with the rags?", "\"I left them in a pile near the back wall. I meant to move them to a metal can in the morning.\""), .direct("Are solvent rags a fire risk?", "\"Yes. They can heat as they dry and ignite without a spark, which is why they belong in a sealed can.\""), .direct("Did {DL} tell you to keep them out?", "\"Not that I recall. We did not have a rule about it.\""), .direct("Did you see any other fire risk?", "\"I did not. Everything else seemed ordinary.\""), .cross("You are the one who left the rags in a pile, aren't you?", "\"Yes, and I feel responsible. I should have used the can.\""), .cross("Did you set the alarm panel?", "\"No. That was {D}'s job. I do not touch the panel.\""), .cross("Did you notice the stock had been moved?", "\"Some of it, yes. I did not ask why.\""), .cross("Did {DL} ask you to stay late that night?", "\"No. I left at the usual time.\""), .cross("Can rags cause a fire that spreads to a whole room?", "\"They can if there is enough fuel nearby. There was a lot of wood in that room.\"")],
        theory: ("{D} set the fire to escape debt.", "Rags ignited on their own."),
        allocution: "\"I panicked about money.\"",
        truths: ("{DL} turned off the alarm panel that night and moved the best stock to a storage unit.", "The rags were left in a pile by a worker, a known fire risk."),
        defendant: [.direct("What happened with the rags?", "\"A worker finished refinishing a piece the day before and left rags in a pile. Solvent rags can heat up and catch fire on their own.\""), .direct("Did you start the fire?", "\"No. I would never burn my own store. It took me years to build.\""), .direct("Why was the alarm off?", "\"I turned it off for a service visit and did not turn it back on. That was careless, but it was not planned.\""), .direct("Why did you sell stock at a discount?", "\"The bank wanted payment and I needed cash. Clearing stock was the only way to keep the lights on.\""), .direct("Why was the best stock in storage?", "\"I was moving it ahead of the sale. I planned to bring it back after the bank problem was settled.\""), .direct("Looking back, how do you feel about losing the store?", "\"Devastated. Everything I owned was in that building, and now people think I did it.\""), .cross("The bank called in your credit line, didn't it?", "\"Yes. It was a hard blow. It does not mean I set a fire.\""), .cross("You turned off the alarm panel that night, didn't you?", "\"The panel was off. I admit that. I forgot to turn it back on.\""), .cross("You moved the best furniture out first, didn't you?", "\"I moved some pieces. I had a reason, and it was about the sale.\""), .cross("The investigator found accelerant, didn't they?", "\"I heard that. Refinishing solvent would give the same result.\""), .cross("You collect insurance if the store burns, don't you?", "\"There is a policy. Everyone has one. It does not mean I wanted a fire.\"")],
        openings: ("A furniture store burned in the early hours with solvent-soaked rags in the back room. The bank had called in a credit line, the stock was discounted and the best pieces moved, and the alarm was off. The State will show the report and the records.", "Solvent rags can catch fire by themselves, and a worker left them in a pile. {D} says the fire was an accident of the trade, and the refinisher will tell you what was left behind."),
        closings: ("A called credit line, stock sold off cheap, the best pieces in storage, an alarm turned off, and a back room full of accelerant. The fire was no accident.", "Rags left in a pile after refinishing work are a known cause of fires. The State has not proved {D} lit anything."),
        timeline: [(-60, "Credit line called."), (-7, "Stock sold off."), (0, "3 a.m.: the fire."), (2, "Claim filed.")],
        identified: "The fire report.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let fentanylSalineSwapV1 = SmallCases.make(
        key: "story.fentanylSalineSwap",
        category: .drugs,
        headlines: ["Pharmacy Tech Diverted Opioids From Operating Room Carts", "Patients Woke in Pain After Routine Procedures"],
        law: "prescriptionFraud",
        threshold: 7,
        spec: "Obtained a controlled substance by fraud, deceit and misrepresentation, on or about {DATE}.",
        ages: 25...60,
        victim: false,
        summary: "{D}, a pharmacy technician who stocked the operating room carts, drew up syringes for operating rooms and returned some filled with water on {DATE} and for weeks before. {DL} says a cart restocking error caused the weak doses.",
        state: [E(.forensic, 3, "Syringe Testing", "Diluted syringes returned from rooms."), E(.digital, 3, "Cart Access Log", "{D}'s code on every flagged cart."), E(.document, 2, "Waste Forms", "Waste signed alone.")],
        defense: [E(.document, 1, "Restocking Memo", "A memo about a mixed-up supplier lot.")],
        role: "Anesthesia manager",
        exam: [.direct("What first made you suspect a problem?", "\"Patients were waking up with pain after surgeries that should have been fully managed. We pulled syringes back from rooms and tested them.\""), .direct("What did testing show?", "\"Diluted syringes. Some held mostly water where the opioid should have been, which meant patients were under-medicated.\""), .direct("What does the cart access log show?", "\"{D}'s code was on every cart that held a flagged syringe. No other code appears on all of them.\""), .direct("What about the waste forms?", "\"Opioid waste was signed alone. Policy requires a second signature, and these forms had only one.\""), .direct("How long did this go on?", "\"For weeks before {DATE}, based on the dates of flagged syringes and the carts they came from.\""), .direct("What did {DL} say about it?", "\"{D} blamed a restocking error and pointed to a memo about a supplier lot.\""), .cross("Did you see {DL} dilute a syringe?", "\"No. No camera shows that. My evidence is the carts, the codes, and the testing.\""), .cross("Did the recall affect real lots in the building?", "\"Yes. Two lots were affected. I checked that carefully.\""), .cross("Do other people have cart codes?", "\"Yes. Several staff have codes, though not on every flagged cart.\""), .cross("Were all diluted syringes from the recalled lots?", "\"I could not confirm that. Some lot numbers were unreadable.\""), .cross("Did {DL} cooperate after the first report?", "\"{D} answered questions and agreed to testing. I did not see resistance.\"")],
        defenseRole: "Circulating nurse",
        defenseExam: [.direct("What is your role in surgery?", "\"I am a circulating nurse. I handle supplies and medications in the room during cases.\""), .direct("Did you notice problems with syringes?", "\"Yes. A few times a patient was more awake than expected, and the syringe felt oddly weak.\""), .direct("What did you do?", "\"I reported it and set the syringe aside. I thought it might be a bad lot.\""), .direct("Did you hear about the supplier recall?", "\"I did. A memo told us two lots were affected. That seemed to explain some of it.\""), .direct("How did {DL} act when you reported it?", "\"Cooperative. {D} looked at the lot numbers with me and agreed it was worth checking.\""), .direct("Did you ever see {DL} tamper with anything?", "\"No.\""), .cross("Were all flagged syringes from the recalled lots?", "\"I do not know. I did not check each lot number.\""), .cross("Did you ever see {DL} alone with the carts?", "\"Yes, at times. That was normal for a tech who stocks them.\""), .cross("Did {DL} seem unwell during that period?", "\"{D} seemed tired and distracted. I did not know why.\""), .cross("Did you sign waste with {DL}?", "\"Sometimes. Not always. I was busy in the room.\""), .cross("Did you ever suspect someone was diverting drugs?", "\"I wondered at times. I had no proof and I kept it to myself.\"")],
        theory: ("{D} took the drug and refilled syringes.", "A supplier mix-up."),
        allocution: "\"I was struggling.\"",
        truths: ("{DL} had been in treatment for an opioid problem and relapsed.", "The supplier recall did affect two lots in the building."),
        defendant: [.direct("What is your job at the hospital?", "\"I work as a pharmacy technician, stocking the operating room carts with syringes and supplies.\""), .direct("Did you dilute any syringes?", "\"No. I drew them up as instructed. If a dose was weak, something went wrong in the supply, not in my hands.\""), .direct("What about the supplier lot?", "\"A memo said two lots were mixed up. I think a restocking mix-up caused weak doses.\""), .direct("Why did you sign waste alone?", "\"We were short-staffed and nurses were busy. It became a habit, and I know I should have waited.\""), .direct("Do you have a personal struggle?", "\"Yes. I have been in treatment for an opioid problem. I will not hide that.\""), .direct("Did you take drugs from the carts?", "\"I do not believe so. I was fighting my own battle, but I did not touch patient doses.\""), .cross("Your code is on every flagged cart, isn't it?", "\"Yes, because I stock every cart. That does not mean I tampered with them.\""), .cross("You signed waste forms alone, didn't you?", "\"I did, more than I know I should have. That was wrong.\""), .cross("You relapsed, didn't you?", "\"I did during that period. That is part of why this is so painful to talk about.\""), .cross("Someone replaced opioid with water in these syringes, didn't they?", "\"Someone did. I cannot say who, and I did not.\""), .cross("The recall memo covered two lots, not dozens of syringes, correct?", "\"It covered two lots in the building. Maybe more were affected than we know.\"")],
        openings: ("A pharmacy technician stocked the operating room carts. For weeks, syringes returned from surgeries held water instead of opioid, {D}'s code is on every flagged cart, and waste was signed alone. The State will show the testing and the log.", "A supplier recall hit two lots in the building, and a nurse noticed weak syringes too. {D} says a restocking error caused it, and a circulating nurse will tell you what the rooms saw."),
        closings: ("Diluted syringes, {D}'s code on every cart, waste signed alone, and a relapse during those same weeks. Patients paid for it on the operating table.", "A real recall and a real restocking mix-up. The State has not proved {D} diluted a single syringe or that the recalled lots do not explain the weak doses."),
        timeline: [(-45, "Patient complaints rise."), (0, "A syringe is tested."), (10, "Lab results."), (25, "Charges.")],
        identified: "A cart access log.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let clinicWithoutLicenseV1 = SmallCases.make(
        key: "story.clinicWithoutLicense",
        category: .whiteCollar,
        headlines: ["Mobile 'Doctor' Treated Patients Out of a Van", "Weight Loss Shots From an Unlicensed Practitioner"],
        law: "falsePretenses",
        threshold: 7,
        spec: "Obtained money from {V} and others by false pretenses, on or about {DATE}.",
        ages: 28...65,
        victim: true,
        summary: "{D} parked a van outside a gym and sold weight loss injections and 'blood panels' on {DATE}, collecting $18,000 from clients like {V}. {DL} says a nurse practitioner stood behind every sale.",
        state: [E(.document, 3, "Licensing Board Letter", "No license for {D}."), E(.forensic, 3, "Vial Analysis", "Saline with a food dye."), E(.digital, 2, "Payment App", "Payments into {D}'s account.")],
        defense: [E(.document, 1, "Practitioner Agreement", "A signed supervision agreement.")],
        role: "Board investigator",
        exam: [.direct("How did your office learn about {DL}?", "\"A complaint came in from a gym member who had paid for injections from a van. We opened a case and visited.\""), .direct("What did the licensing board find?", "\"No license of any kind for {D}. {D} was not a physician, nurse, or any licensed provider.\""), .direct("What was in the vials?", "\"Lab analysis found saline with food dye. There was no medication in them.\""), .direct("What did {D} sell?", "\"Weight loss injections and what {D} called blood panels, sold from a van outside a gym.\""), .direct("How much did clients pay?", "\"About $18,000 in total, including the money {V} paid, according to the payment app records.\""), .direct("What did {DL} claim?", "\"That a nurse practitioner stood behind every sale and that the services were legitimate.\""), .direct("What did the licensing board's records show about {D}'s coat?", "\"It had a doctor's title stitched on it, though {D} held no license of any kind. The title was meant to make clients believe {D} was a medical provider.\""), .cross("Did you see {DL} inject a client?", "\"No. I reviewed documents and statements. I did not witness a sale.\""), .cross("Did {DL} show you the supervision agreement?", "\"Yes. A signed agreement exists. We looked into whether it was valid.\""), .cross("Was the practitioner's license valid?", "\"It was valid when the agreement was signed. That is not in dispute.\""), .cross("Who made the vials?", "\"I could not determine that. Their source remains unclear.\""), .cross("Did clients complain about harm?", "\"Mostly they complained about getting nothing for their money.\"")],
        defenseRole: "Gym member",
        defenseExam: [.direct("How do you know {DL}?", "\"We both belong to the same gym. I saw {D}'s van in the lot several times.\""), .direct("Did you buy anything?", "\"I bought one injection series. {D} said a practitioner supervised everything.\""), .direct("What did {DL} tell you?", "\"That a nurse practitioner stood behind the work and reviewed each client.\""), .direct("Did you see any paperwork?", "\"{D} showed me a signed agreement with a practitioner. It looked official.\""), .direct("How did you feel after the injections?", "\"Nothing happened. I did not lose weight or feel anything at all.\""), .direct("What did you think of the coat?", "\"It had a doctor's title and I took it as a sign of credentials.\""), .direct("Tell the jury how you know {D}.", "\"We belong to the same gym. I saw {D}'s van in the parking lot for weeks before I decided to try the injections for weight loss.\""), .direct("What did {D} tell you before you bought the injections?", "\"{D} said a nurse practitioner stood behind the work and that the injections were safe. I did not see any paperwork, and I did not ask for any.\""), .direct("What did you pay and what did you receive?", "\"I bought one injection series and paid through a payment app. I got several shots over a few weeks, and I noticed no change in my weight.\""), .cross("Did you ever speak with the practitioner?", "\"No. I only knew what {D} told me.\""), .cross("Did you see the practitioner at the van?", "\"Never once.\""), .cross("Did you check {DL}'s license?", "\"No. I trusted the coat and the agreement.\""), .cross("Did you pay in cash?", "\"I paid through an app.\""), .cross("Would you have bought if {DL} had no practitioner?", "\"No. That mattered a great deal to me.\"")],
        theory: ("{D} posed as a medical provider.", "A licensed partner supervised."),
        allocution: "\"I just wanted people to feel better.\"",
        truths: ("{DL} wore a coat with a doctor's title stitched on.", "The partner's license was valid when the agreement was signed."),
        defendant: [.direct("What did you do in the van?", "\"I offered weight loss injections and simple blood panels to people at the gym, with a practitioner's backing.\""), .direct("What was the arrangement with the practitioner?", "\"I signed a supervision agreement. The practitioner was supposed to stand behind the sales and handle the medical side.\""), .direct("What did you wear?", "\"A coat with a doctor's title stitched on. I thought it made clients comfortable. I see now how it looks.\""), .direct("What was in the vials?", "\"I was told they were the correct product. I did not know they were saline with dye.\""), .direct("Did you intend to cheat anyone?", "\"No. I thought I was running a legitimate business with a partner. I made mistakes about licensing.\""), .direct("Looking back, how do you feel about {V}?", "\"Sorry. I did not want anyone to be harmed or to pay for nothing.\""), .direct("What did the supervision agreement with the nurse practitioner say?", "\"It said the practitioner would supervise my work. The practitioner's license was valid when we signed, and I thought that covered every sale I made from the van.\""), .cross("You have no license, do you?", "\"Correct. I do not hold a license of my own. I relied on my partner.\""), .cross("The coat said doctor, didn't it?", "\"Yes. It was a bad choice, and I understand why people trusted it.\""), .cross("The vials held only saline and dye, didn't they?", "\"That is what the lab says. I did not make them.\""), .cross("You took $18,000 from clients, didn't you?", "\"I took payments for services. I thought they were legitimate.\""), .cross("You sold blood panels without any lab, didn't you?", "\"I sent samples to a service. I thought that covered it.\"")],
        openings: ("{D} parked a van outside a gym and sold weight loss injections and blood panels, taking $18,000 from clients like {V}. The board has no license for {D}, and the vials held saline with food dye. The State will show the letter and the analysis.", "{D} says a nurse practitioner stood behind every sale, and a signed supervision agreement says so. A gym member will tell you what {D} said and showed."),
        closings: ("No license, a doctor's title on the coat, saline in the vials, and $18,000 taken from clients. {D} sold medicine that was not medicine.", "A signed agreement with a practitioner whose license was valid. The State has not proved {D} knew the vials were saline or meant to cheat anyone."),
        timeline: [(-45, "The van appears."), (0, "{V} buys a package."), (20, "Complaint to the board."), (40, "Van seized.")],
        identified: "Payment records.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let fakeIllnessFundraiserV1 = SmallCases.make(
