        ages: 30...65,
        victim: false,
        summary: "{D} bought $40,000 of call options on a company on {DATE}, two days before a takeover bid. {D}'s sibling sat on the company board. {DL} says the buy came from a chart pattern.",
        state: [E(.digital, 3, "Brokerage Records", "A first-ever options purchase in this company."), E(.digital, 3, "Phone Records", "A call with the board member the night before."), E(.document, 2, "Profit Statement", "$118,000 gained.")],
        defense: [E(.document, 1, "Chart Printouts", "Saved charts with notes from the prior month.")],
        role: "Securities investigator",
