        defenseRole: "Sibling",
        defenseExam: [.direct("How are you related to {DL}?", "\"I am the sibling. We are close and talk several times a week.\""), .direct("What is your role at the company?", "\"I serve on the board. I attend meetings and review financial reports.\""), .direct("What did you and {DL} talk about the night before?", "\"Family, work, ordinary things. {D} asked how the quarter was going.\""), .direct("Did you mention a takeover?", "\"No. I did not tell {D} anything about a bid.\""), .direct("Did you know about the bid then?", "\"I knew confidential matters existed, and I was careful. I did not share them.\""), .direct("How are you coping with what happened?", "\"Terrible. I never wanted my family dragged into this.\""), .direct("Tell the jury what you and {D} talked about the night before the purchase.", "\"We talked about family, work, and ordinary things. {D} asked how the quarter was going, and I answered in general terms, the way I would with anyone.\""), .direct("Did you know a takeover bid was coming when you spoke with {D}?", "\"I knew the board was discussing confidential matters, but I never told {D} anything about a bid. I was careful not to share what I learned in meetings.\""), .direct("Have you and {D} ever discussed investments before?", "\"Rarely. {D} follows charts on {D}'s own, and I have never given {D} a tip. I would not risk my board seat or my family's trust that way.\""), .cross("Did you tell {DL} how the quarter was going?", "\"I said it was going fine. That was general.\""), .cross("Was the call unusual?", "\"We talk often, but I did think about the timing afterward.\""), .cross("Did {DL} ask any questions about the company?", "\"Only the one about the quarter.\""), .cross("Did you tell anyone else about the bid?", "\"No. Only those who needed to know.\""), .cross("Did you warn {DL} not to trade?", "\"No. I did not think of it.\"")],
        theory: ("{D} traded on a tip from the board.", "A technical chart play."),
