        defendant: [.direct("Why did you buy those options?", "\"I had studied the chart for weeks. I saw a pattern that suggested the stock would move up.\""), .direct("Did you speak to your sibling before buying?", "\"Yes, we talk often. I asked how the quarter was going, as I would with anyone in the family.\""), .direct("What did your sibling say?", "\"Nothing about a takeover. We talked about work being busy and the family.\""), .direct("Where are your chart notes?", "\"I kept printouts with notes from the month before. They show I was watching the stock already.\""), .direct("Why was this your first options trade in that company?", "\"I had been trading other stocks and decided to try options here because of the pattern.\""), .direct("How do you feel about the profit?", "\"Uneasy now. It looks bad, but I made that trade for my own reasons.\""), .direct("How did you come to study the company's chart?", "\"I followed the stock for weeks and saved printouts with notes. I wrote those notes before my first call with my sibling, and the pattern looked strong to me.\""), .cross("Your sibling sits on the board, doesn't {D.he}?", "\"Yes. That is no secret.\""), .cross("You called the night before the buy, didn't you?", "\"We talked, yes. I did not ask about a bid.\""), .cross("You made $118,000 two days later, didn't you?", "\"The trade paid off. I did not know why it would.\""), .cross("You had never bought options in this company before, had you?", "\"No. This was the first time.\""), .cross("You put $40,000 on one trade, didn't you?", "\"Yes. I believed in the chart.\"")],
        openings: ("{D} bought $40,000 of call options in a company two days before a takeover bid, and {D}'s sibling sits on its board. It was {D}'s first options purchase there and the profit was $118,000. The State will show the records and the call.", "A chart pattern, printed and annotated weeks before, and a sibling who talks to {D} every week. {D} says the trade came from the charts, and the sibling will tell you what was said."),
        closings: ("A first-ever options purchase, a call to a board member the night before, and $118,000 in profit two days later. A takeover bid followed, and the timing is not a coincidence.", "A chart pattern printed and annotated weeks before the call, and a sibling who says nothing about a bid was shared. The State has not proved that {D} traded on a tip from the board."),
        timeline: [(-30, "Chart notes made."), (-3, "A late call."), (-2, "The options buy."), (0, "The bid is announced.")],
