    static let mowerOnTheBypassV1 = SmallCases.make(
        key: "story.mowerOnTheBypass",
        category: .traffic,
        headlines: ["Wedding Guest Drives Golf Cart Onto State Highway at .14", "Deputy Stops Golf Cart With Dress Shoes on Pedals"],
        law: "dwi",
        spec: "Operated a vehicle on a highway while impaired, on {DATE}.",
        ages: 21...65,
        victim: false,
        summary: "At 10:40 p.m. on {DATE}, a deputy saw {D} driving a golf cart on a state highway with one headlight dim and a bouquet strapped to the roof. The deputy stopped the cart, smelled alcohol and ran a breath test at 11:05 p.m.: .14. {D} had left a nearby wedding. {D} says the golf cart was on a private lane.",
        state: [E(.document, 3, "Breath Result", "A breath alcohol concentration of .14 at 11:05 p.m."), E(.video, 2, "Body Camera", "The deputy finds {D} in the cart in a travel lane."), E(.document, 2, "Highway Map", "The lane where the cart was stopped is a state highway, not private."), E(.statement, 2, "Deputy", "Followed the cart for a quarter mile in the lane.")],
        defense: [E(.statement, 1, "Private Lane", "{DL} says the cart was on a private lane."), E(.document, 1, "Venue Map", "A map showing a service lane next to the venue.")],
        role: "Sheriff's deputy",
        exam: [.direct("Tell us about your work as a sheriff's deputy.", "\"I patrol the roads in the county, and I work many nights. I make traffic stops, respond to calls, and perform impaired driving checks on the state highway.\""), .direct("What did you see at 10:40 p.m. on {DATE}?", "\"I saw a golf cart in the travel lane of the state highway with one headlight dim and a bouquet of flowers strapped to the roof. I followed it for a quarter mile.\""), .direct("What happened when you stopped the cart?", "\"I walked up and smelled alcohol on {D}. I asked where {D} was headed, and {D} said home from a wedding at a nearby venue.\""), .direct("What did the breath test show?", "\"I ran a breath test at 11:05 p.m. and the result was .14. That is well over the legal limit, and I recorded it on my body camera.\""), .direct("Was the cart on a state highway or a private lane?", "\"A state highway. I checked the map afterward. The lane where I stopped the cart is a public travel lane, and it is not private property.\""), .direct("How did you determine where the cart came from?", "\"{D} said the cart came from a wedding nearby. The venue has a service lane beside it, but the cart was well past it by the time I stopped it.\""), .cross("Did you see {D} swerve or hit anything?", "\"No. The cart moved slowly and stayed in its lane. I did not see any collision. The only concern was the dim headlight and the cart being on the highway.\""), .cross("Is there a private service lane next to the venue?", "\"Yes. The venue sent me a map showing a lane beside the building. It runs next to the venue, and I cannot say that it was clearly marked at the road.\""), .cross("Was {D} cooperative during the stop?", "\"Yes. {D} was polite and explained where the cart came from. {D} did not argue, and {D} took the breath test when I asked.\""), .cross("Did {D} say where the golf cart came from?", "\"{D} said it belonged to the wedding venue and that the shuttle had stopped running. I did not verify that with the venue that night.\""), .cross("Could someone think the service lane led to the highway?", "\"Possibly. The lane ends near the highway, and the signs are small. But the highway is a clear public road, with traffic and lines.\"")],
        defenseRole: "Wedding guest",
        defenseExam: [.direct("Walk us through how you know {D}.", "\"I am a friend of {D}'s and we were both guests at the wedding. We have known each other for years and I sat at the same table that night.\""), .direct("What did you see {D} drink at the wedding?", "\"I saw {D} drinking over the evening. It was a long reception, and {D} had several drinks. I did not count them, but it was a good amount.\""), .direct("Why did {D} take a golf cart?", "\"The shuttle had already left, and the venue's cart was sitting near the lot. {D} said it would be a short ride to the road, and nobody stopped {D}.\""), .direct("Did {D} tell you where {D} was going?", "\"Yes. {D} said home. I believed {D} meant to take the service lane out to the road, because that is how the guests were told the shuttle would go.\""), .direct("What did you think about {D} driving?", "\"I did not think much about it. I thought it was a slow cart on a private lane, and I did not realize it would reach the highway.\""), .direct("What did the other guests do when {D} drove off?", "\"Most guests were still dancing and did not notice. A few waved as the cart left the lot, and nobody tried to stop {D} or asked where {D} was going.\""), .cross("Did you try to stop {D} from driving?", "\"No. I did not. In hindsight, I should have, and I wish I had offered {D} a ride or called someone to help.\""), .cross("Did you see {D} leave the venue?", "\"I saw {D} leave the lot. I did not see where the cart went after that. I only learned about the stop the next morning.\""), .cross("Was the service lane marked at the highway?", "\"I do not remember any sign. It was dark, and the lane seemed to run toward the road. I cannot say it was clearly marked.\""), .cross("Did the venue warn guests about driving the carts?", "\"I did not hear a warning. The carts were used by staff, and guests were not supposed to take them, but nobody enforced that.\""), .cross("Did {D} seem impaired to you?", "\"A little. {D} was cheerful and a bit unsteady. I did not think it was bad enough to stop {D}, and I was wrong about that.\"")],
        theory: ("{D} drove a golf cart on a highway while impaired.", "{D} was on a private lane."),
        allocution: "\"I put people in danger and I'm sorry.\"",
        truths: ("{DL} had been drinking at the wedding for four hours.", "{DL} thought the service lane continued to the highway."),
        defendant: [.direct("Please tell us about your night at the wedding.", "\"I went to a friend's wedding and stayed for about four hours. I had drinks, danced, and enjoyed the evening, and I did not plan to drive a car.\""), .direct("Why did you take the golf cart?", "\"The shuttle had gone and I wanted to go home. The cart was parked near the venue, and I thought the service lane was a safe way to get out.\""), .direct("What did you think about the lane you were driving on?", "\"I thought it was the service lane. It looked like a continuation of the venue's lane, and I did not realize I had moved onto the state highway.\""), .direct("Why did you strap a bouquet to the roof?", "\"Someone gave me the bouquet at the wedding. I did not want to lose it, so I tied it to the roof. It was a silly decision.\""), .direct("What happened when the deputy stopped you?", "\"I was surprised. I told the deputy I had come from the wedding. I took the breath test and I did not argue with the result.\""), .direct("How has this affected you?", "\"I feel foolish. I should not have driven anything after drinking. I would not do it again, and I am sorry for putting anyone at risk.\""), .cross("You had been drinking for four hours, hadn't you?", "\"Yes. I had been at the wedding for about four hours, and I was drinking for most of it. I know that is a long time.\""), .cross("The test was .14, wasn't it?", "\"Yes. That is what the test showed. I do not dispute the result, and I know it is well above the legal limit.\""), .cross("You drove past the venue before the stop, didn't you?", "\"Yes. I drove past the venue. I thought I was still on the service lane, but I was already on the highway.\""), .cross("One of your headlights was dim, wasn't it?", "\"Yes. The cart's headlight was dim, and I knew that. I did not think about how visible I would be on a highway at night.\""), .cross("You could have called someone for a ride, couldn't you?", "\"Yes. I could have called a friend or a ride service. I did not, and I regret that decision more than anything else.\"")],
        openings: ("At 10:40 on a night in {DATE}, a deputy saw a golf cart on a state highway with a dim headlight and a bouquet on its roof. The driver, {D}, had left a nearby wedding, and a breath test showed .14.", "The defense will explain that {D} was leaving a wedding on a service lane that seemed to lead to the road, in a cart borrowed because the shuttle was gone. A confusing lane and a short ride do not make a crime."),
        closings: ("A golf cart on a state highway at night, a dim headlight, a bouquet on the roof, and a breath test of .14. {D} had been drinking for four hours and chose to drive anyway, and the State has proved it.", "A wedding, a missing shuttle, a service lane that seemed to continue to the road, and a dim headlight made a short ride into a long one. {D} did not mean to drive on the highway."),
        timeline: [(0, "10 p.m.: {D} leaves the wedding."), (0, "10:40 p.m.: the deputy stops the cart."), (0, "11:05 p.m.: the breath test reads .14."), (1, "The venue sends its map.")],
        identified: "The deputy's stop and the cart identify {D}.",
        notDone: ["The breath test's calibration record was never produced.", "The venue's shuttle plan was never asked about."],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let buriedCoinDigV1 = SmallCases.make(
        key: "story.buriedCoinDig",
        category: .property,
        headlines: ["Metal Detector Enthusiast Digs Up Horse Pasture at Dawn and Breaks Irrigation Line", "Farm Trail Camera Shows Digger With Shovel and Detector"],
        law: "injuryRealProperty",
        spec: "Willfully injured the real property of {V}, a horse farm, by digging holes in a pasture, on {DATE}.",
        ages: 18...70,
        victim: true,
        summary: "At dawn on {DATE}, {D} walked onto a horse pasture with a metal detector and a shovel and dug eleven holes. A shovel struck an irrigation line and flooded part of the pasture. The farm's trail camera recorded {D}. Repairs to the line and the pasture cost the farm $2,100. {D} says the caretaker said it was fine to detect.",
        state: [E(.video, 3, "Farm Trail Camera", "{D} digs holes in the pasture from 5:50 to 6:40 a.m."), E(.document, 3, "Repair Invoice", "$2,100 to repair the irrigation line and level the pasture."), E(.physical, 2, "Holes", "Eleven holes spread across the pasture."), E(.statement, 2, "{V}", "Never gave anyone permission to dig.")],
        defense: [E(.statement, 1, "Caretaker Said Fine", "{DL} says the caretaker said it was fine to metal detect."), E(.document, 1, "Club Message", "A club chat message about a 'friendly farm' with 'old coins.'")],
        role: "Farm owner",
        exam: [.direct("What is your role at the farm?", "\"I own it. I keep horses and manage the property, with a caretaker helping on busy days.\""), .direct("What happened at dawn on {DATE}?", "\"{D} walked onto the pasture with a metal detector and a shovel and dug eleven holes over about fifty minutes.\""), .direct("What does the trail camera show?", "\"{D} digging from 5:50 to 6:40 a.m., clearly, holes appearing across the pasture.\""), .direct("What damage resulted?", "\"A shovel struck an irrigation line and flooded part of the pasture, and the horses could not use it.\""), .direct("What did it cost?", "\"$2,100 to repair the line and level the pasture, per the repair invoice.\""), .direct("Did you give permission?", "\"Never. I did not give {D} or anyone a permission to dig on my land.\""), .direct("What did the club's attitude toward your pasture seem to be?", "\"I told {D} two years earlier not to detect on my land. I never gave anyone permission to dig, and I was shocked when I saw the trail camera clip.\""), .cross("Did you ever hear {DL} say a caretaker approved?", "\"Only after the fact. {D} said so when I spoke with {D.him} later.\""), .cross("Did {DL} try to hide the digging?", "\"No. It was at dawn in open view of a trail camera.\""), .cross("Who was the caretaker that morning?", "\"A teenager who works part time. I did not authorize the teenager to give permission.\""), .cross("Did {DL} offer to pay?", "\"I received a message offering to help. We had not settled it.\""), .cross("Were the holes filled?", "\"Some were. Not all of them.\"")],
        defenseRole: "Hobby group member",
        defenseExam: [.direct("How do you know {DL}?", "\"We belong to the same detecting club. We go out together sometimes.\""), .direct("What was the club chat about?", "\"A message about a friendly farm with old coins. It sounded like an invitation.\""), .direct("How does {DL} act in the field?", "\"Careful, usually. {D} fills holes and respects the land.\""), .direct("Did you go with {DL} that morning?", "\"No. I was not there. I heard about it afterward.\""), .direct("Does {DL} intend harm?", "\"No. {D} loves the hobby and would not hurt a farm.\""), .direct("Walk us through what you know about the club chat before that morning.", "\"A message went around the club about a friendly farm with old coins. It sounded like a place where detecting would be welcome, and several members were excited.\""), .direct("Did {D} tell you the owner had approved?", "\"{D} said the caretaker waved {D} in and said it was fine. I took that as approval, and I did not ask for any more than that.\""), .direct("How do metal detecting clubs usually handle permission on farms?", "\"Members are told to get permission from the owner. Sometimes a caretaker or a family member says yes, and members take it at face value.\""), .cross("Did the chat message come from the owner?", "\"No. It came from a club member.\""), .cross("Did anyone in the club get permission from the owner?", "\"I do not know.\""), .cross("Did {DL} mention the old warning?", "\"Not to me.\""), .cross("Did {DL} fill the holes?", "\"I do not know. I heard there were eleven holes left.\""), .cross("Would you dig without the owner's say?", "\"No. I would ask the owner myself.\"")],
        theory: ("{D} dug up a pasture without permission.", "The caretaker said it was fine."),
        allocution: "\"I took what wasn't mine, and I'm sorry for it.\"",
        truths: ("{DL} had been told by the farm owner two years earlier not to detect there.", "The caretaker, a teenager, waved {DL} in."),
        defendant: [.direct("Why were you on the pasture?", "\"I belong to a detecting club. A message said the farm was friendly and had old coins.\""), .direct("Did anyone say you could detect there?", "\"The caretaker waved me in and said it was fine. I took that as permission.\""), .direct("Had you been told not to detect there before?", "\"The owner told me two years ago not to. I thought things had changed.\""), .direct("Why did you dig eleven holes?", "\"Each signal could have been an old coin. I dug as much as seemed needed.\""), .direct("Did you know about the irrigation line?", "\"No. I had no idea it was there until the water started to flow.\""), .direct("What did you do when it flooded?", "\"I panicked and stopped. I should have called the owner right away.\""), .direct("Why did you believe it was fine to detect there?", "\"A teenager at the farm waved me in, and a club chat described the farm as friendly to detecting. I took it to mean I had permission.\""), .cross("The owner told you not to detect there, didn't {V.he}?", "\"Yes, years ago. I thought the caretaker's word replaced it.\""), .cross("The caretaker is a teenager, isn't the caretaker?", "\"Yes, a teenager. I did not think about whether that counted.\""), .cross("You dug before sunrise, didn't you?", "\"Around dawn. It was a good time for signals.\""), .cross("You did not ask the owner first, did you?", "\"No. I assumed the caretaker could speak for the farm.\""), .cross("The line cost $2,100 to repair, didn't it?", "\"So I understand. I am willing to pay.\"")],
