        exam: [.direct("What was taken from your yard?", "\"Twenty-four decorative metal windmills, from my front yard overnight on {DATE}.\""), .direct("What did the neighbor's camera show?", "\"{D} loading windmills into a rolling cart at 1 a.m.\""), .direct("Where did you find them?", "\"On the town green the next morning, standing in rows, with a sign reading Windmill Park.\""), .direct("What did the windmills cost?", "\"I bought them over six years, for about $700 total, and each one meant something to me.\""), .direct("Did you give permission?", "\"Never. I had never agreed to move them anywhere.\""), .direct("What had happened before?", "\"{D} had asked to borrow them earlier and I said no.\""), .direct("What did the sign on the town green say and what did you do when you saw it?", "\"The sign read Windmill Park. I recognized every windmill in the rows because I bought them over six years, and I called the town the same morning to have them returned.\""), .cross("Did you see {DL} take the windmills?", "\"Only on the neighbor's video. I was asleep.\""), .cross("Were the windmills damaged?", "\"No. They were set out in rows and looked fine.\""), .cross("Did {DL} leave a note?", "\"Yes. A note on the green said back Sunday.\""), .cross("Did {DL} try to sell them?", "\"No. They stayed on the green.\""), .cross("Would you have said no again?", "\"Yes. I did say no once.\"")],
        defenseRole: "Friend who helped",
        defenseExam: [.direct("How do you know {DL}?", "\"We are friends. I helped carry things that night.\""), .direct("What was the project?", "\"An art installation on the town green, with the windmills in rows.\""), .direct("Was the owner told?", "\"I thought a note would do. I did not know the owner had said no.\""), .direct("What did the note say?", "\"Back Sunday. It was meant to reassure people.\""), .direct("How did {DL} act?", "\"Excited. {D} had a vision for it.\""), .direct("Did you think it was theft?", "\"No. I thought it was a loan for art.\""), .direct("Walk us through what happened the night you helped {D}.", "\"We loaded the windmills into a rolling cart around one in the morning. I carried several, and {D} explained it was an art installation for the town green.\""), .direct("What did {D} say about the owner's permission?", "\"{D} said a note would do, and that the windmills would be back on Sunday. I did not know the owner had said no when {D} first asked to borrow them.\""), .direct("How did {D} arrange the windmills on the green?", "\"Carefully, in neat rows. {D} planted each one and placed a sign reading Windmill Park. {D} wanted people to enjoy them, and nothing was damaged.\""), .direct("Did you worry about whether the windmills belonged to someone?", "\"A little, but {D} told me a note would cover it and that the owner would get them back on Sunday. I trusted {D}, and I did not think it would turn into a case.\""), .cross("Did {DL} tell you the owner said no?", "\"Not at first.\""), .cross("Did you ask the owner?", "\"No.\""), .cross("Did you help load the cart?", "\"Yes.\""), .cross("Did you go at night for a reason?", "\"To finish before dawn.\""), .cross("Would you have done it knowing the answer was no?", "\"No. I would have stopped.\"")],
        theory: ("{D} took the windmills and put them on display.", "{D} borrowed them for an art project."),
        allocution: "\"It was a stupid decision and someone else paid for it.\"",
        truths: ("{DL} had asked {V} to borrow them and been told no.", "The note said back on Sunday."),
        defendant: [.direct("Why did you move the windmills?", "\"It was an art project. I wanted to show them together in a public place.\""), .direct("Did you plan to return them?", "\"Yes. I left a note on the green saying back Sunday.\""), .direct("Had you asked the owner?", "\"I asked earlier to borrow them and was told no. I did it anyway, which was wrong.\""), .direct("Why did you go at 1 a.m.?", "\"So nobody would stop me before I finished the display.\""), .direct("How did you transport them?", "\"A rolling cart. I made several trips.\""), .direct("How has this affected you?", "\"Embarrassed. I turned a friend's collection into a stunt.\""), .direct("What did the note on the green say?", "\"It said the windmills would be back on Sunday. I left it so no one would think they were stolen, but I know I should have asked the owner again.\""), .direct("Why did you choose the town green for your art project?", "\"It is where people gather, and I wanted neighbors to see the windmills in rows as one piece of art. I meant it to be a gift for the whole town, and nothing was damaged.\""), .cross("You were told no, weren't you?", "\"Yes. I was told no, and I went ahead.\""), .cross("You took all twenty-four, didn't you?", "\"Yes. I moved all of them.\""), .cross("You went at 1 a.m. to avoid being seen, didn't you?", "\"Mostly. I did not want an argument.\""), .cross("You left only a note, didn't you?", "\"I left a note. I did not contact the owner.\""), .cross("The owner never gave you permission, did {V.he}?", "\"No. I knew that.\"")],
        openings: ("Twenty-four decorative metal windmills vanished from {V}'s yard at 1 a.m., and a neighbor's camera shows {D} loading them into a cart. By morning they stood on the town green under a sign reading Windmill Park. The State will show the camera and the purchase records.", "An art project, a note that said back Sunday, and a friend who helped carry. {D} never meant to keep them, and the friend will tell you why."),
        closings: ("Twenty-four windmills taken at 1 a.m. from an owner who had said no, set out in rows on the green. {D} took them.", "An art project and a note promising return on Sunday. The State has not proved {D} meant to permanently keep what was taken."),
        timeline: [(0, "1 a.m.: {D} loads the windmills."), (0, "7 a.m.: {V} finds the yard empty."), (0, "9 a.m.: the windmills are found on the green."), (1, "The town returns them.")],
        identified: "The neighbor's camera identifies {D}.",
        notDone: ["The town green's maintenance crew was never asked who found them.", "The windmills' return was never documented."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let creamPieSmashV1 = SmallCases.make(
        key: "story.creamPieSmash",
        category: .violent,
        headlines: ["Protester Throws Milkshake at School Board President at Open Meeting", "Meeting Video Shows Cup Thrown After Public Comment Cut Off"],
        law: "simpleAssault",
        spec: "Assaulted {V} by throwing a milkshake in {V.his} face, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "At a school board meeting on {DATE}, {D} was cut off at the end of the three-minute public comment period. At 7:25 p.m. {D} stepped forward and threw a milkshake in the face of {V}, the board president. {V} needed eye care for irritation. The meeting video recorded the throw. {D} says it was a protest and not meant to harm.",
        state: [E(.video, 3, "Meeting Video", "{D} steps forward and throws a milkshake at {V} at 7:25 p.m."), E(.document, 2, "Medical Note", "Eye irritation from the milkshake treated that evening."), E(.statement, 2, "Board Secretary", "Saw {D} bring a cup into the meeting."), E(.physical, 1, "Cup", "A paper cup with a lid found on the floor.")],
        defense: [E(.statement, 1, "Protest", "{DL} says it was a protest and not meant to harm."), E(.document, 1, "Public Comment Card", "A card showing {DL}'s three-minute comment.")],
        role: "Board secretary",
        exam: [.direct("What is your role?", "\"I am the board secretary. I take minutes and manage the public comment cards.\""), .direct("What happened at the meeting on {DATE}?", "\"{D} was cut off at the end of the three-minute comment period and stepped forward at 7:25 p.m.\""), .direct("What did {DL} do?", "\"{D} threw a milkshake in the face of {V}, the board president. The video shows it clearly.\""), .direct("What did you see earlier?", "\"{D} brought a cup into the meeting. I noticed it because it had a lid and a straw.\""), .direct("What was {V}'s condition?", "\"Eye irritation requiring care that evening. A medical note documents it.\""), .direct("What was found afterward?", "\"A paper cup with a lid on the floor.\""), .direct("What did you see {D} do before the meeting reached the public comment?", "\"I saw {D} carrying a paper cup with a lid into the meeting. The cup stayed in {D}'s hands until the comment period ended, and then {D} stepped forward.\""), .cross("Did you see {DL} aim?", "\"The video shows the throw. It does not prove where {D} aimed.\""), .cross("Did {DL} say anything before throwing?", "\"I did not hear any words.\""), .cross("Did {DL} stay at the scene?", "\"Yes. {D} did not run.\""), .cross("Was {V} badly hurt?", "\"Irritated and shaken. Treated and sent home that evening.\""), .cross("Was the cup full?", "\"It was mostly full. I did not see how much remained.\"")],
        defenseRole: "Other speaker",
        defenseExam: [.direct("What was {DL} like when speaking?", "\"Passionate. {D} had a strong view and was cut off.\""), .direct("What does the comment card show?", "\"{D} signed up for three minutes.\""), .direct("Did you see the throw?", "\"Yes. It happened fast.\""), .direct("What did {DL} do after?", "\"Stood still. {D} looked shocked.\""), .direct("Describe what you saw of {D} at the meeting.", "\"I spoke at the same meeting, in the same public comment period. I saw {D} sign up for three minutes and wait with the rest of us for the turn.\""), .direct("How did {D} act while speaking?", "\"{D} was passionate, with a strong view, and spoke quickly because time was short. When the three minutes ended, {D} was cut off in the middle of a sentence.\""), .direct("How did {D} react to being cut off?", "\"{D} looked stunned and then angry. I did not see anything planned, but {D} stepped forward quickly, and I did not realize what was coming.\""), .direct("What did the comment card show about how much time {D} was given?", "\"It showed {D} signed up for three minutes, the same as every other speaker. I saw the card myself, and the rule was applied evenly to everyone who spoke that night.\""), .direct("Did anything about the evening suggest the board was listening to speakers?", "\"Not really. The board members looked at their papers during several comments, and many speakers said afterward that they felt ignored, which is part of why {D} was so frustrated.\""), .cross("Did you see {DL} carry the cup in?", "\"I noticed a cup.\""), .cross("Did {DL} talk about a protest?", "\"Not to me.\""), .cross("Did {DL} aim at the face?", "\"I could not tell.\""), .cross("Did you speak to {DL} afterward?", "\"Briefly. {D} apologized.\""), .cross("Was the throw sudden?", "\"Yes.\"")],
        theory: ("{D} threw a milkshake at {V}.", "{D} made a symbolic protest."),
        allocution: "\"I lost my temper, and I'm sorry for what I did.\"",
        truths: ("{DL} had planned the throw for a week.", "{DL} threw the milkshake in frustration and did not aim at the face."),
        defendant: [.direct("Why did you speak at the meeting?", "\"I wanted the board to hear a concern. I had a statement prepared.\""), .direct("What happened when time ran out?", "\"I was cut off mid-sentence. I felt ignored and I snapped.\""), .direct("Why did you bring a cup?", "\"I planned the protest for a week. I wanted to make a point.\""), .direct("Did you aim for the face?", "\"I threw it in frustration. I did not mean to hit {V} in the eyes.\""), .direct("What happened after?", "\"I stood there stunned. I realized I had hurt someone.\""), .direct("Do you regret it?", "\"Yes. A protest should use words, not a milkshake.\""), .direct("What were you thinking when you threw the milkshake?", "\"I was frustrated and angry at being cut off. I did not aim at the face, and I did not think about what would happen to the board president.\""), .direct("What did you say to the board before the comment time ended?", "\"I said the board had ignored parents for months and that people deserved to be heard. I was in the middle of a sentence when the clock ran out and the microphone was turned off.\""), .cross("You planned this for a week, didn't you?", "\"Yes. I thought about it for days.\""), .cross("You walked forward on purpose, didn't you?", "\"Yes. I stepped forward and threw.\""), .cross("The milkshake hit {V}'s face, didn't it?", "\"Yes. It did.\""), .cross("You brought the cup into the meeting, didn't you?", "\"Yes. I carried it in.\""), .cross("{V} needed eye care, didn't {V.he}?", "\"I heard so. I feel awful about it.\"")],
        openings: ("At a school board meeting, {D} was cut off after three minutes, stepped forward, and threw a milkshake in the face of {V}, the board president. The meeting video recorded it.", "A cut-off public comment, a card showing three minutes, and a frustrated speaker. A fellow speaker will tell you what the room saw."),
        closings: ("A planned throw, a cup carried into the meeting, and a milkshake in a board president's face at 7:25. {D} had planned it for a week, and {V} needed care for an irritated eye.", "A cut-off comment, three minutes on a card, and a frustrated speaker who did not aim at the face. The State must prove {D} meant to harm {V}, and a symbolic protest is not an assault."),
        timeline: [(0, "7:20 p.m.: {D}'s comment is cut off."), (0, "7:25 p.m.: {D} throws the milkshake."), (0, "7:35 p.m.: deputies are called."), (1, "The school sends the meeting video.")],
        identified: "The meeting video identifies {D}.",
        notDone: ["The meeting rules on public comment were never read in.", "The cup's contents were never tested."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let mascotNappingCaseV1 = SmallCases.make(
        key: "story.mascotNappingCase",
        category: .property,
        headlines: ["Three Sousaphones Taken From Marching Band Bus After Away Game", "Pawn Ticket Shows Brass Sold Two Days After Game"],
        law: "felonyLarceny",
        spec: "Took and carried away property of a school band worth over $1,000, three sousaphones, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "A marching band's bus was parked behind the school after an away game on {DATE}, with three sousaphones stored in the luggage bay. The next morning the bay was open and the horns were gone. A pawn shop took in three matching horns from {D}, a bus driver, two days later and paid $2,400. The horns cost the school $9,000. {D} says the band director said the old horns could be sold.",
        state: [E(.document, 3, "Pawn Ticket", "Three sousaphones pawned by {D} for $2,400."), E(.physical, 3, "Serial Numbers", "The pawned horns' serials match the school's inventory."), E(.document, 2, "Inventory", "Three sousaphones valued at $9,000."), E(.video, 2, "Bus Lot Camera", "{D} loads three cases into a car at 11 p.m.")],
        defense: [E(.statement, 1, "Old Horns", "{DL} says the band director said old horns could be sold."), E(.document, 1, "Director Email", "An email about 'retiring' two old tubas the previous year.")],
        role: "School band director",
        exam: [.direct("Tell the jury about your role at the school.", "\"I direct the marching band. I schedule rehearsals and away games, and I am responsible for the instruments, including the sousaphones stored on our bus.\""), .direct("What happened on the night of the away game?", "\"The band bus was parked behind the school with three sousaphones in the luggage bay. The next morning, the bay was open and all three horns were gone.\""), .direct("How did you find the horns?", "\"Two days later, a pawn shop took in three matching horns from {D}, a bus driver. The shop paid $2,400, and the school learned of the pawn ticket.\""), .direct("How did you know the pawned horns were the school's?", "\"The serial numbers on the horns matched our inventory. We have three sousaphones valued at $9,000, and the numbers on the pawned horns were the same.\""), .direct("What did the bus lot camera show?", "\"{D} loading three cases into a car at 11 p.m. that night. The cases are the size of sousaphone cases, and nobody else was in the lot.\""), .direct("What was the cost to the school?", "\"The horns were worth $9,000, and we had to borrow instruments for the next competition. The students were disappointed, and the band lost a few rehearsals.\""), .cross("Did you ever tell {D} that old horns could be sold?", "\"About a year earlier, I wrote an email about retiring two old tubas. I never told {D} anything about selling sousaphones, and these horns were only three years old.\""), .cross("Was the email about these horns?", "\"No. The email was about two older tubas, not the three sousaphones taken that night. I cannot say what {D} thought, but the email did not describe them.\""), .cross("Had {D} pawned instruments from other buses before?", "\"Yes. I learned that {D} had pawned instruments from other buses in the past. I did not know about that until after the sousaphones went missing.\""), .cross("Who locked the luggage bay that night?", "\"The driver normally locks it. I did not lock it myself, and I cannot say who did that night. In the morning, it was open.\""), .cross("Did {D} have access to the bus?", "\"Yes. {D} drove it and had keys. Several others, including students, had access to the lot, but no one else was on the camera loading cases.\"")],
        defenseRole: "Band parent",
        defenseExam: [.direct("Explain to the jury how you know {D}.", "\"My child plays in the band. I help on trips and I have ridden the band bus many times. I know {D} as the driver who is always at the school.\""), .direct("What do you know about the luggage bay on the bus?", "\"It locks with a key, but it is often left open at the end of a long night. The driver usually locks it, though I have seen it left open.\""), .direct("Was {D} near the bus that night?", "\"Yes. {D} was around the bus after the game. {D} was in the lot loading things into the car, and I did not think anything of it at the time.\""), .direct("Did {D} ever mention selling old horns?", "\"Once. {D} said the director talked about retiring old tubas and that some could be sold. I heard that and assumed it was a general discussion.\""), .direct("What kind of person is {D} around the students?", "\"Kind and patient. {D} helps load the instruments and looks out for the kids. I have never seen {D} do anything dishonest around the band.\""), .direct("What did you think when you heard about the pawn ticket?", "\"I was surprised. I did not think {D} would knowingly take anything. I thought it was a misunderstanding about which horns were being retired.\""), .cross("Did you see {D} take the sousaphones?", "\"No. I saw {D} loading things into a car, but I did not see what was in the cases. I only know what I heard afterward.\""), .cross("Was the bay open in the morning?", "\"Yes. I heard that it was open and that the horns were gone. I do not know who left it open, and I did not check myself.\""), .cross("Did {D} offer to carry the horns on other trips?", "\"Once. {D} carried cases on a trip last year. That was part of the job, and it did not seem unusual at the time.\""), .cross("Do you know whether the school's director told {D} the horns could be sold?", "\"I do not know. I only know what {D} said. I was not in the meeting where the old tubas were discussed.\""), .cross("Would you expect a driver to sell school property?", "\"No. That would not be normal. A driver should ask first, and I think {D} should have done that before pawning anything.\"")],
        theory: ("{D} took school horns and pawned them.", "{D} thought retired horns could be sold."),
        allocution: "\"I took what wasn't mine, and I'm sorry for it.\"",
        truths: ("{DL} had pawned instruments from other buses.", "The retired tuba email was real and {DL} confused it with these horns."),
        defendant: [.direct("What are your duties as a bus driver?", "\"I drive the band bus to games and the school's activity trips. I keep it clean, I watch the luggage bay, and I have worked for the school for years.\""), .direct("Why did you take the horns?", "\"I thought they were the old horns the director mentioned in an email. I thought retired horns could be sold, and I wanted to help the school get some money.\""), .direct("How did you get the horns out of the bay?", "\"I loaded three cases into my car around eleven that night. I did not hide it. I was in a hurry, and I did not check the serial numbers.\""), .direct("Why did you pawn them for $2,400?", "\"I needed a quick buyer, and the pawn shop gave me a ticket. I planned to give the money to the school, but I never got that far.\""), .direct("What did you do when the school asked about the horns?", "\"I told them what I thought. I said the director had said the old horns could be sold. I was shocked to learn they were three years old.\""), .direct("How are you coping with what happened?", "\"Honestly, I feel terrible. I made a mistake and I confused two things. I should have asked before touching anything, and I am sorry to the school.\""), .cross("These horns were three years old, weren't they?", "\"Yes. I thought they were older. I did not check, and I know I should have looked at the inventory before taking anything.\""), .cross("You pawned them for $2,400, didn't you?", "\"Yes. I signed the pawn ticket in my own name. I did not use another name or hide it from anyone.\""), .cross("The serial numbers match the school's inventory, don't they?", "\"Yes. I did not check them. If I had, I would have seen that they were the school's current horns and not the retired ones.\""), .cross("You pawned instruments from other buses before, didn't you?", "\"Yes. Those were old instruments that the school was getting rid of. I thought this was the same kind of situation, but it was not.\""), .cross("You never asked the director before you took them, did you?", "\"No. I own that. I assumed the email gave me permission, and I did not think about asking again.\"")],
        openings: ("A band bus sat behind the school after an away game with three sousaphones in the bay. By morning the horns were gone, and two days later {D}, the bus driver, pawned three matching horns for $2,400.", "The defense will present an email about retiring old tubas, a driver who confused those with these horns, and a friend who heard {D} mention it. A mistaken belief is not an intent to steal."),
        closings: ("Three horns loaded into a car at 11 p.m., three horns on a pawn ticket two days later, and serial numbers that match the school's inventory. The school lost $9,000 and a few rehearsals to this.", "A misunderstood email and a bus bay left open that night. The State has not proved that {D} knew these horns were not retired, and an open bay invites more than one suspect."),
        timeline: [(0, "Evening: the horns are loaded in the bay."), (0, "11 p.m.: {D} loads three cases."), (2, "{D} pawns the horns."), (3, "The school finds the pawn ticket.")],
        identified: "The pawn ticket is signed by {D}.",
        notDone: ["The bus driver was never asked who locked the bay.", "The other band members were never interviewed."],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let giantPumpkinSmashV1 = SmallCases.make(
        key: "story.giantPumpkinSmash",
        category: .property,
        headlines: ["Champion Squash Injected With Bleach Before Fair Weigh-In", "Syringe Found Near Prize Squash and Bleach Test Positive"],
        law: "injuryPersonalProperty",
        spec: "Willfully injured the personal property of {V}, a giant squash, causing it to rot before judging, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} had a giant squash worth a $2,000 prize waiting for the county fair weigh-in on {DATE}. Overnight, {D} entered the barn and injected the squash with bleach using a syringe. By morning it was soft and leaking. A barn camera recorded {D} with a syringe. {D} says the squash was already rotting and {D.he} was testing it.",
        state: [E(.video, 3, "Barn Camera", "{D} injects the squash with a syringe at 1:10 a.m."), E(.physical, 3, "Syringe", "A syringe with bleach residue found in {D}'s truck."), E(.document, 2, "Lab Test", "The squash tests positive for bleach and chlorine."), E(.document, 2, "Fair Rules", "A $2,000 prize for the heaviest squash.")],
        defense: [E(.statement, 1, "Testing", "{DL} says the squash was rotting and {D.he} was testing it."), E(.document, 1, "Photo of Squash", "A photo of a soft spot on the squash dated the day before.")],
        role: "Fair judge",
        exam: [.direct("What is your role at the fair?", "\"I am a fair judge. I weigh entries and enforce the rules.\""), .direct("What was at stake with the squash?", "\"A $2,000 prize for the heaviest squash. {V}'s entry was waiting for weigh-in on {DATE}.\""), .direct("What does the barn camera show?", "\"{D} injecting the squash with a syringe at 1:10 a.m.\""), .direct("What did the lab find?", "\"Bleach and chlorine in the squash.\""), .direct("What was found in {DL}'s truck?", "\"A syringe with bleach residue.\""), .direct("What was the squash like in the morning?", "\"Soft and leaking. It could not be entered.\""), .direct("What did the lab test show about the squash?", "\"It tested positive for bleach and chlorine. The syringe found in {D}'s truck had bleach residue, and the squash had gone soft and was leaking by morning.\""), .direct("What was the weigh-in process and what happened to the squash that morning?", "\"The squash was waiting for the weigh-in, and by seven in the morning it was soft and leaking. The weigh-in for that entry was cancelled, and the grower lost the chance at the prize.\""), .cross("Did you see {DL} inject bleach?", "\"The camera shows an injection. I do not know what was in the syringe from the video alone.\""), .cross("Could a squash rot on its own?", "\"Yes. It happens, which is why the lab test matters.\""), .cross("Did {DL} have a rival entry?", "\"Yes, in the same class.\""), .cross("Did {DL} try to hide in the barn?", "\"No. {D} walked in plainly and stood in the camera's view.\""), .cross("Was the soft spot photographed?", "\"A photo exists. Its date is the day before.\"")],
        defenseRole: "Fair judge",
        defenseExam: [.direct("What is your role at the fair?", "\"I am a fair judge for the produce classes. I have judged giant vegetables for many years and know what healthy ones look like.\""), .direct("Did you see the squash before the incident?", "\"Yes, the afternoon before. I walked the barn and noticed a soft spot near the stem end of that squash.\""), .direct("What did the soft spot look like?", "\"A slightly sunken, damp patch. It is the kind of thing that sometimes means internal rot is starting, though not always.\""), .direct("Did you speak with {DL} about it?", "\"{D} asked me about soft spots on big squash that day. It was an ordinary question for someone who grows them.\""), .direct("Does the photo match what you saw?", "\"It does. The photo of the soft spot is dated the day before, and it shows the same patch I noticed.\""), .direct("How would you describe {DL}'s character?", "\"Competitive but fair. I have never known {D} to cheat in judging or to damage another grower's entry.\""), .direct("Tell us what you saw of the squash the afternoon before.", "\"I walked the barn and noticed a slightly sunken, damp patch on the squash. I took a photo that was dated the day before, and I thought it needed to be looked at.\""), .direct("How do growers usually test for rot in a giant squash?", "\"Some tap it, some use a probe, and some draw a small sample with a syringe. It is not normal to inject anything, but testing is common.\""), .direct("What did you think when you heard about the bleach?", "\"I was shocked. I could not believe someone would inject bleach. But I also could not rule out that the squash was already rotting when {D} tested it.\""), .cross("Could a soft spot alone make a squash leak by morning?", "\"Not likely. It would take far more damage than a small soft spot to leave it leaking.\""), .cross("Would a grower normally inject another person's squash to test it?", "\"No. A grower should tell the judges and let us decide what to do.\""), .cross("Did {DL} tell you about any barn visit that night?", "\"No. Nothing was said to me about it.\""), .cross("Did you see {DL} with a syringe that day?", "\"No. I did not see a syringe.\""), .cross("Did you inspect the squash after it was ruined?", "\"Yes. It was soft and leaking, and the smell was harsh and chemical.\"")],
        theory: ("{D} poisoned a rival's squash.", "{D} tested a rotting squash."),
        allocution: "\"I knew it wasn't mine. I'll pay it back.\"",
        truths: ("{DL} had entered a rival squash in the same class.", "The soft spot was real and {DL} wanted to know why."),
        defendant: [.direct("Why did you go into the barn at 1 a.m.?", "\"I had seen a soft spot on the squash the day before and could not stop worrying about it. The barn was quiet, so I went in alone.\""), .direct("What were you trying to find out?", "\"Whether the squash was rotting inside. A soft spot on a giant squash can mean the flesh is going bad, and I wanted to understand why.\""), .direct("Why did you use a syringe?", "\"I thought I could draw a small sample from the core and see if it was sour or watery. It seemed gentler than cutting into a prize entry.\""), .direct("What was in the syringe?", "\"I have been over that many times. I cannot say what was in it with certainty, and I never intended to put bleach into anything.\""), .direct("Do you have a squash of your own at the fair?", "\"Yes, in the same class. I know that makes it look bad, but my squash was nowhere near that one and I was not trying to knock out a rival.\""), .direct("Looking back, how do you feel about the ruined squash?", "\"Sick about it. {V} spent a whole season on that squash and I turned it into a soft, leaking mess.\""), .direct("Why did you have a rival squash entered in the same class?", "\"I grow squash too and entered one in the same class. I did not enter it to win by hurting another grower's squash, and I wanted to know why this one was soft.\""), .cross("The camera shows you injecting the squash, doesn't it?", "\"It shows me with a syringe at the squash, yes. I am not denying I was there or that I did it.\""), .cross("You entered a squash in the very same class, didn't you?", "\"Yes, I did. I understand why the timing and the prize money make people suspicious of me.\""), .cross("A syringe with bleach residue was found in your truck, wasn't it?", "\"Yes. I use bleach for cleaning in my work, and I kept the syringe in the truck for small jobs.\""), .cross("You went at 1 a.m. so nobody would see you, didn't you?", "\"I went when it was quiet. I did not want a crowd around while I poked at a prize entry.\""), .cross("By morning the squash was soft and leaking and could not be weighed, correct?", "\"Correct. I saw it myself. I feel responsible for what happened to it.\"")],
        openings: ("{V} had a giant squash worth a $2,000 prize. Overnight, {D} entered the barn and injected it with bleach. A barn camera recorded the syringe. The State will show the video, the syringe, and the lab test.", "A soft spot, a photo dated the day before, and a judge who wanted to know why. {D} says the squash was already rotting."),
        closings: ("A syringe, bleach, a rival entry in the same class, and a ruined squash on the morning of the weigh-in. The camera shows {D} in the barn at 1:10, and the lab shows what was in the squash.", "A soft spot that was already there, a photo taken the day before, and a grower who wanted to know why. The State has not proved that {D} meant to ruin a $2,000 prize."),
        timeline: [(0, "1:10 a.m.: {D} injects the squash."), (0, "7 a.m.: the squash is found soft."), (0, "9 a.m.: weigh-in is cancelled for the squash."), (2, "The lab reports bleach.")],
        identified: "The syringe and the barn camera tie to {D}.",
        notDone: ["The syringe's contents were never compared with the bleach.", "The barn's door log was never read."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let spotlightHuntV1 = SmallCases.make(
        key: "story.spotlightHunt",
        category: .publicOrder,
        headlines: ["Turkey Taken Out of Season Over Corn Pile at Dawn", "Game Camera Shows Hunter Baiting Field and Dropping Bird"],
        law: "misdLarceny",
        spec: "Took and carried away wildlife belonging to the State, a turkey, by baiting out of season, on {DATE}.",
        ages: 18...65,
        victim: false,
        summary: "At 6:15 a.m. on {DATE}, a wildlife officer found {D} in a camouflage blind beside a field with a pile of corn. {D} had shot a turkey ten minutes earlier. The season was closed and baiting is banned. A game camera on the field showed {D} spreading corn the previous evening. {D} says the corn was already there.",
        state: [E(.video, 3, "Game Camera", "{D} spreads corn at 6 p.m. the day before."), E(.physical, 3, "Turkey and Shotgun", "A freshly shot turkey and a shotgun in the blind."), E(.document, 2, "Season Calendar", "The season is closed on {DATE}."), E(.statement, 2, "Wildlife Officer", "Found {D} in the blind and the corn pile ten yards away.")],
        defense: [E(.statement, 1, "Corn Already There", "{DL} says the corn was already there from a farmer."), E(.document, 1, "Farmer Statement", "The farmer says deer were fed there in winter.")],
        role: "Wildlife officer",
        exam: [.direct("Tell us about your work as a wildlife officer.", "\"I enforce hunting and fishing rules in the county. I patrol fields and woods at dawn, check licenses and bag limits, and respond to reports of baiting and out-of-season hunts.\""), .direct("What did you find at 6:15 a.m. on {DATE}?", "\"I found {D} in a camouflage blind beside a field. A freshly shot turkey and a shotgun were in the blind, and a pile of corn lay ten yards away.\""), .direct("Why does the corn matter?", "\"Baiting is banned. Spreading corn to draw turkeys within range is a violation, and it gives a hunter an unfair advantage over the birds and other hunters.\""), .direct("What was the season status that day?", "\"The turkey season was closed. A season calendar shows the last day was well before {DATE}, and the shot had been fired about ten minutes before I arrived.\""), .direct("What did the game camera show?", "\"A game camera on the field showed {D} spreading corn at 6 p.m. the day before. It clearly shows {D} carrying the corn and scattering it in the field.\""), .direct("How did you collect the camera and the evidence?", "\"I retrieved the game camera that morning and photographed the turkey, the shotgun, and the corn pile. I wrote it all down and gave it to the prosecutor.\""), .cross("Did the farmer feed deer on that field?", "\"In winter, yes. The farmer told me the farmer fed deer there. But that was a different pile of corn, in a different part of the field.\""), .cross("Could the corn pile ten yards away have been left from the farmer?", "\"I do not think so. The corn near the blind looked fresh, and the camera shows {D} spreading it the evening before.\""), .cross("Did {D} cooperate with you?", "\"Yes. {D} was polite and showed me the turkey and the shotgun. {D} did not try to leave, and {D} answered my questions.\""), .cross("Did {D} say the season was open?", "\"{D} said {D} thought the season was open. I told {D} it was closed, and {D} seemed surprised. I cannot say what {D} knew.\""), .cross("Did anyone else see {D} spread the corn?", "\"No. Only the game camera saw it. I did not see {D} spread it myself, and no witness has come forward to say they watched it.\"")],
        defenseRole: "Hunting buddy",
        defenseExam: [.direct("Walk us through how you know {D}.", "\"We hunt together. I have gone out with {D} many mornings, sitting in blinds and waiting for turkeys. I know {D} to be a careful hunter.\""), .direct("Did you see {D} put out corn?", "\"Not that I know of. I was not with {D} the evening before, and I did not see {D} spread anything in the field.\""), .direct("What did you see of the field that morning?", "\"It looked baited. There was a pile of corn within sight of the blind. I did not think about it until the officer arrived.\""), .direct("Did {D} shoot the turkey?", "\"Yes. I was nearby and heard the shot. {D} came out of the blind with the turkey, and {D} was excited about it.\""), .direct("How does {D} usually handle hunting rules?", "\"{D} usually follows them. {D} asks questions and checks the calendar most seasons. This time {D} slipped, but it is not how {D} usually behaves.\""), .direct("What did you think when you heard about the corn?", "\"I was surprised. I did not know about it until later. I assumed the corn was from the farmer, and I did not think {D} would spread more.\""), .cross("Was the field baited?", "\"It looked baited to me. A pile of corn like that near a blind is a problem, and I would not have hunted over it.\""), .cross("Was it in season?", "\"I did not check the calendar. I assumed it was open because {D} had planned to go out, and I did not ask.\""), .cross("Did you tell the officer what you knew?", "\"Yes. I said what I saw. I did not say anything about the corn that I did not know, and I did not defend it.\""), .cross("Would you have hunted there that morning?", "\"No. I would not have hunted over a pile of corn. I do not know why {D} chose that spot, and I would not have chosen it.\""), .cross("Did {D} ask you about the season dates?", "\"No. {D} never asked me. If {D} had asked, I would have told {D} that the calendar was closed, and we would not have gone.\"")],
        theory: ("{D} baited a field and shot a turkey out of season.", "The corn was already there."),
        allocution: "\"It was childish, and I know it.\"",
        truths: ("{DL} had bought the corn the day before.", "The farmer's winter feed was a different pile."),
        defendant: [.direct("What can you tell us about your hunting?", "\"I have hunted turkey for years. I go out early, I sit in a blind, and I try to follow the rules as I understand them each season.\""), .direct("Where did the corn come from?", "\"It was already there. A farmer had put out feed in winter, and I thought the corn near the blind was left from then.\""), .direct("What were you doing at the field the evening before?", "\"I was moving some corn around so I could set up a blind. I did not think of it as baiting, and I did not think I was breaking a rule.\""), .direct("Why did you think the season was open?", "\"I thought the dates were later than they were. I did not check the calendar, and I made a mistake that I now understand.\""), .direct("What did you do when the officer arrived?", "\"I told the officer what happened. I showed the turkey and the shotgun, and I did not argue about what I had done.\""), .direct("How do you feel about it now?", "\"I feel foolish. I should have checked the calendar and cleared the field. I wish I had asked someone before going out that morning.\""), .cross("The camera shows you spreading corn, doesn't it?", "\"Yes. It shows me moving corn. I was setting up my blind, and I did not think that counted as baiting.\""), .cross("You had bought the corn the day before, hadn't you?", "\"Yes. I bought a bag of corn the day before the hunt. I used it for my own purposes, and I should not have used it on that field.\""), .cross("The season was closed, wasn't it?", "\"Yes. I know that now. I did not check, and I should have, because I know it is my responsibility as a hunter.\""), .cross("You shot the turkey, didn't you?", "\"Yes. I shot it ten minutes before the officer arrived. I am not denying that, and I accept responsibility for it.\""), .cross("The farmer's feed was a different pile, wasn't it?", "\"Yes. The farmer's pile was farther away. I know that is a weakness in my story, and I should have been clearer about it from the start.\"")],
        openings: ("At 6:15 on a morning in {DATE}, a wildlife officer found {D} in a camouflage blind beside a field with a pile of corn ten yards away. A turkey had just been shot, the season was closed, and a game camera showed {D} spreading corn the evening before.", "The defense will present a farmer who fed deer on that field, a hunter who thought the corn was already there, and a mistake about the season dates. A hunter's honest mistake is not an intent to bait."),
        closings: ("A turkey shot out of season, a pile of corn ten yards from the blind, and a game camera that shows {D} spreading it the evening before. Baiting is banned, and the evidence is clear.", "A blind on a field with corn already there, and a hunter who thought the season was open. The State has not proved {D} meant to bait a turkey, and an honest mistake is not a crime."),
        timeline: [(0, "6 p.m. the day before: {D} spreads corn."), (0, "6:05 a.m.: {D} shoots the turkey."), (0, "6:15 a.m.: the officer arrives."), (1, "The officer retrieves the game camera.")],
        identified: "The game camera identifies {D}.",
        notDone: ["The corn's purchase was never traced.", "The season's closing notice was never read in."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let electionSignSabotageV1 = SmallCases.make(
        key: "story.electionSignSabotage",
        category: .publicOrder,
        headlines: ["Volunteer Spray Paints X on Twenty-Five Opponent's Yard Signs", "Phone Video Shows Painted Signs Along County Road"],
        law: "injuryPersonalProperty",
        spec: "Willfully injured the personal property of {V}, campaign signs, causing damage of $600, on {DATE}.",
        ages: 18...70,
        victim: true,
        summary: "On {DATE} at 6 a.m., {D} walked along a county road and sprayed a red X on twenty-five of {V}'s campaign signs. A driver recorded the spraying on a phone. The campaign replaced the signs at a cost of $600. {D} says the signs were mine-field markers of a rival campaign and the paint was a joke.",
        state: [E(.video, 3, "Driver Phone Video", "{D} sprays a red X on signs along the road at 6:05 a.m."), E(.physical, 2, "Painted Signs", "Twenty-five signs with red X marks."), E(.document, 2, "Replacement Order", "$600 for twenty-five new signs."), E(.physical, 2, "Paint Can", "A red spray can in {D}'s car.")],
        defense: [E(.statement, 1, "A Joke", "{DL} says the paint was a joke and the signs were not ruined."), E(.document, 1, "Photo of Sign", "A photo showing paint that rubbed off with solvent.")],
        role: "Campaign volunteer",
        exam: [.direct("What is your role?", "\"I am a campaign volunteer. I help place signs.\""), .direct("What did you learn on {DATE}?", "\"Twenty-five of {V}'s signs were sprayed with a red X.\""), .direct("What does the video show?", "\"{D} spraying signs along the road at 6:05 a.m.\""), .direct("What did it cost?", "\"$600 for twenty-five new signs.\""), .direct("What was found in {DL}'s car?", "\"A red spray can.\""), .direct("How did you react?", "\"Angry. It felt like an attack on the campaign.\""), .direct("What did you learn about the paint used on the signs?", "\"It was a red spray can, and a can like it was found in {D}'s car. The paint was washable, but we still had to replace twenty-five signs at a cost of $600.\""), .direct("What did the campaign do after volunteers found the signs?", "\"We took photos, called the sheriff, and ordered twenty-five replacements. Volunteers spent the day putting up new signs along the county road so the campaign would not lose visibility before the election.\""), .direct("How did you learn about the driver's video?", "\"The driver posted the clip and sent it to the campaign. The video shows a person walking along the road and spraying a red X on each sign at about 6:05 in the morning.\""), .cross("Did you see {DL} spray the signs yourself?", "\"No. I saw the driver's video and the painted signs.\""), .cross("Was the paint washable?", "\"Some came off with solvent. Not all of it.\""), .cross("Did {DL} deny doing it?", "\"No. {D} admitted it.\""), .cross("Were the signs usable afterward?", "\"Some could be cleaned. We replaced the rest.\""), .cross("Did {DL} offer to pay?", "\"I received an offer. We did not settle it.\"")],
        defenseRole: "Fellow volunteer",
        defenseExam: [.direct("How do you know {DL}?", "\"We both volunteer for the same campaign, and I have seen {D} at events and in the volunteer chat for weeks.\""), .direct("Did {DL} talk about the signs?", "\"{D} joked about them, the way volunteers joke about the other side. It was banter, not a plan to wreck anything.\""), .direct("Did you see the paint come off?", "\"Yes. I tried it on a sample, and it wiped away with solvent and a rag without harming the sign.\""), .direct("What did {DL} say when it came out?", "\"That it was meant as a joke and that {D} was sorry it was taken so seriously.\""), .direct("How would you describe {DL}?", "\"Friendly and a bit of a prankster. I have not seen {D} do anything mean-spirited.\""), .direct("Tell the jury what you know about {D}'s sense of humor.", "\"{D} jokes a lot, the way volunteers do during long campaigns. {D} made light of the signs, and I thought nothing of it until I saw what happened.\""), .direct("What did the photo you took show about the paint?", "\"A sign with paint that rubbed off under solvent. It showed that the paint could be wiped away, which is why I think {D} meant it as a joke.\""), .direct("Did you ever see {D} damage campaign property before?", "\"No. {D} has volunteered for campaigns for years and never damaged anything. This surprised me, and I did not think {D} meant to cause damage.\""), .cross("Did you spray any signs yourself?", "\"No. I had no part in it.\""), .cross("Did you know in advance that {DL} would do it?", "\"No. I learned about it afterward.\""), .cross("Did all the paint come off every sign?", "\"I only tested a sample. I cannot say about all twenty-five.\""), .cross("Did the campaign still have to buy replacements?", "\"Yes. I understand it replaced them.\""), .cross("Would a joke between campaigns cost the other side money?", "\"It did here. I can see that, even if {D} did not mean it.\"")],
        theory: ("{D} ruined twenty-five campaign signs.", "{D} played a joke with removable paint."),
        allocution: "\"I'm sorry for the trouble I caused.\"",
        truths: ("{DL} had been in the rival campaign's volunteer chat for weeks.", "The paint was washable and {DL} meant it as a joke."),
        defendant: [.direct("Why did you spray the signs?", "\"It was a joke I thought was harmless. I grabbed a can of washable paint and made an X on the signs along the road.\""), .direct("Who are you working with?", "\"I have been in a rival campaign's volunteer chat for weeks. We trade jokes about the other side's signs all the time.\""), .direct("Why did you go out at dawn?", "\"Early morning is quiet on that road. I wanted to finish before traffic picked up, and I was not thinking about consequences.\""), .direct("How many signs did you mark?", "\"About twenty-five, along a stretch of the county road. I kept going because each one felt like part of the same silly stunt.\""), .direct("Did you think the signs were ruined?", "\"No. The paint was washable and I believed it would wipe off. I did not think anyone would have to buy new signs.\""), .direct("Looking back, how do you feel?", "\"Embarrassed. A joke on someone else's campaign is not a joke to them, and I should have known better.\""), .direct("What was the rival campaign chat you were part of?", "\"I had been in a rival campaign's volunteer chat for weeks. I treated it as a joke between campaigns, and I did not think anyone would be hurt.\""), .cross("You sprayed twenty-five signs belonging to {V}, didn't you?", "\"Yes. I did, and I will not pretend otherwise.\""), .cross("You did it before sunrise, didn't you?", "\"Around six in the morning, yes. I did not want anyone to stop me.\""), .cross("You volunteer for the rival campaign, don't you?", "\"Yes. I am a volunteer for it, which is why this looks like sabotage.\""), .cross("A driver filmed you spraying, didn't {D.he}?", "\"Yes. I saw a car slow down. I did not think much of it until later.\""), .cross("The campaign paid $600 to replace the signs, didn't it?", "\"So I have heard. I am willing to pay it back.\"")],
        openings: ("At 6 a.m., {D} walked along a county road and sprayed a red X on twenty-five of {V}'s campaign signs. A driver recorded it. The State will show the video, the signs, and the can.", "Paint that rubs off, a photo proving it, and a joke between campaigns. A fellow volunteer will tell you how it was meant."),
        closings: ("Twenty-five signs, a red X on each, a can in {D}'s car, and a driver's video from 6:05 that morning. The campaign paid $600 to replace what {D} ruined.", "Paint that rubs off, a photo that proves it, and a joke between campaigns. The State has not proved that {D} meant to destroy anything, and washable paint is not a ruin."),
        timeline: [(0, "6:05 a.m.: {D} starts painting."), (0, "6:30 a.m.: the last sign is painted."), (0, "8 a.m.: volunteers find the signs."), (1, "The driver sends the phone video.")],
        identified: "The driver's phone video identifies {D}.",
        notDone: ["The spray paint was never matched to a can.", "The campaign's replacement cost was never itemized."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let oysterBedPoachV1 = SmallCases.make(
        key: "story.oysterBedPoach",
        category: .property,
        headlines: ["Clammer Takes Undersized Clams From Closed Flats at Night Tide", "Marine Patrol Finds Buckets and Headlamp on Mud Flat"],
        law: "misdLarceny",
        spec: "Took and carried away property of the State, shellfish from a closed area, on {DATE}.",
        ages: 18...65,
        victim: false,
        summary: "At 11:30 p.m. on {DATE}, a marine patrol officer saw a headlamp on a closed shellfish flat at low tide. {D} was digging clams and had four buckets nearly full. Many were undersized. A closure sign stood at the access point. {D} says the sign was knocked over and {D.he} thought the flat was open.",
        state: [E(.physical, 3, "Clam Buckets", "Four buckets with several hundred clams, many undersized."), E(.document, 3, "Closure Order", "The flat is closed to shellfish harvest for the season."), E(.video, 2, "Officer Camera", "{D} digs on the flat with a headlamp at 11:35 p.m."), E(.document, 2, "Sign Photo", "A closure sign at the access point lying on its side.")],
        defense: [E(.statement, 1, "Sign Down", "{DL} says the sign was knocked over and the flat looked open."), E(.document, 1, "Tide Chart", "A low tide at 11:40 p.m. that night.")],
        role: "Marine patrol officer",
        exam: [.direct("How would you describe your job as a marine patrol officer?", "\"I patrol the coast and tidal flats, enforce shellfish rules, and check harvesters for licenses, size limits, and closed areas. I often work nights during low tide.\""), .direct("What did you see at 11:30 p.m. on {DATE}?", "\"I saw a headlamp bobbing on a shellfish flat at low tide. When I walked out, I found {D} digging clams with four buckets nearly full.\""), .direct("What was in the buckets?", "\"Several hundred clams, and many were undersized. Size limits protect the beds, so harvesting small clams damages the population for the following seasons.\""), .direct("Was the flat closed to harvest?", "\"Yes. A closure order had closed the flat to shellfish harvest for the whole season. The agency confirmed the order, and notices were posted at the boat ramp.\""), .direct("What did your camera record?", "\"It shows {D} digging on the flat with a headlamp at 11:35 p.m. It also shows the buckets, and I seized them at about 11:50.\""), .direct("Where was the closure sign?", "\"At the access point, but it was lying on its side. I photographed it, and I cannot say how it fell or how long it had been down.\""), .cross("Was the sign down when you arrived?", "\"Yes. I photographed it on its side. It could have been knocked over by wind, a vehicle, or a person, and I cannot say which.\""), .cross("Were there other signs or notices about the closure?", "\"A notice was posted at the boat ramp. There was no second sign on the flat itself, and the only one at the access point was lying down.\""), .cross("Did {D} try to hide or run when you approached?", "\"No. {D} stayed where {D} was and answered my questions. {D} did not run, and {D} told me {D} thought the flat was open.\""), .cross("Was it dark enough that undersized clams would be hard to see?", "\"It was dark, and a headlamp lights a small area. A digger could have trouble judging size in the bucket, though measuring is the harvester's job.\""), .cross("Did {D} have a valid harvest license?", "\"Yes. {D} held a license for shellfish harvest. The problem was the closed flat and the undersized clams, not the license.\"")],
        defenseRole: "Fellow clammer",
        defenseExam: [.direct("Explain to the jury how you know {D}.", "\"I am a fellow clammer. We have dug the same flats for years, and we often see each other at the ramp before a night tide.\""), .direct("What did you see at the flat access that night?", "\"I did not see a sign standing. I saw one lying on its side, and I did not think it meant the flat was closed that night.\""), .direct("Had you dug that flat before?", "\"Yes, last year. It was open then, and many diggers assume it is open again each season unless the sign is clearly standing.\""), .direct("How do diggers usually learn about closures?", "\"From signs at the flat and notices at the ramp. Many of us check the state website, but plenty of people just go by the sign.\""), .direct("What kind of digger is {D}?", "\"Careful and honest. {D} usually measures clams and returns small ones to the flat. I was surprised to hear what happened that night.\""), .direct("What did {D} tell you about that night?", "\"{D} said the sign was down and the flat looked open. {D} was upset about the clams and said {D} would have stopped if {D} had known.\""), .cross("Is it normal to dig at night on that flat?", "\"Not usually. Most people dig at daylight tides, but a low tide at night happens, and some of us go anyway.\""), .cross("Did you know the flat was closed this season?", "\"No. I did not know either. I learned about the closure afterward, when I heard about what happened to {D}.\""), .cross("Did {D} ever mention the closure to you?", "\"No. {D} never mentioned it before that night. If {D} had known, I think {D} would have said something about it.\""), .cross("Can you say whether {D} knew about the closure order?", "\"I cannot say for certain. I can only say what {D} told me, which is that {D} did not see a sign and did not know.\""), .cross("You do not know whether the sign was standing earlier that day, do you?", "\"No. I walked through at dusk and noticed it down. I cannot say who knocked it over or when.\"")],
        theory: ("{D} harvested clams from a closed flat.", "{D} thought the flat was open."),
        allocution: "\"I'm ashamed of it, Your Honor. I want to make it right.\"",
        truths: ("{DL} had read the closure notice posted at the boat ramp.", "The sign at the access point was down."),
        defendant: [.direct("Please describe your clamming.", "\"I have dug clams for years. I go at low tide, often at night, and I share the catch with family and neighbors. I take pride in following the rules.\""), .direct("Why did you go to that flat on {DATE}?", "\"It was a good low tide and I wanted clams. I had dug that flat the year before, and I assumed it was open again this season.\""), .direct("What did you see at the access point?", "\"The sign was down, lying on its side. I did not see it clearly in the dark, and with it down the flat looked open to me.\""), .direct("Did you know the flat was closed?", "\"No. I did not. A notice was posted at the boat ramp, but I did not read it. I was in a hurry to catch the tide.\""), .direct("Why were so many clams undersized?", "\"It was dark and I was digging quickly. I did not measure each one, and I meant to sort them later, as I always do at home.\""), .direct("What did you do when the officer arrived?", "\"I stopped digging and told the officer I thought the flat was open. I gave over my license and handed over the buckets without argument.\""), .cross("A closure notice was posted at the boat ramp, wasn't it?", "\"Yes. I did not read it. I walked past it in a hurry, and I know that I should have stopped to check before I went out.\""), .cross("You dug four buckets nearly full, didn't you?", "\"Yes. I dug four buckets. I know that is a lot of clams, and it is more than I usually take on a night.\""), .cross("Many of the clams were undersized, weren't they?", "\"Yes, according to the officer. I did not measure them in the dark, and I understand that is my responsibility.\""), .cross("You had read the closure notice, hadn't you?", "\"I had read about closures in general, but I did not read this notice. I cannot say I had no warning at all.\""), .cross("You dug at night so you would not be seen, didn't you?", "\"No. I dig at night because that is when the tide is low. I wore a bright headlamp, and I did not try to hide.\"")],
        openings: ("At 11:30 on a night in {DATE}, a marine patrol officer saw a headlamp on a closed shellfish flat and found {D} digging clams. Four buckets were nearly full, many clams were undersized, and the season's closure was posted at the ramp.", "The defense will present a closure sign that lay on its side, a harvester who has dug that flat for years, and a notice at the ramp that no one read. A fallen sign and an honest mistake are not a plan to poach."),
        closings: ("Four buckets of clams from a closed flat, many of them undersized, dug at night with a headlamp. A closure order and a posted notice told every harvester that the flat was off limits.", "A flat closed by a notice may look the same as any other flat when the sign lies on its side. The State has not proved that {D} knew the flat was closed."),
        timeline: [(0, "11:30 p.m.: the officer sees the headlamp."), (0, "11:35 p.m.: {D} is digging."), (0, "11:50 p.m.: the officer seizes the buckets."), (1, "The agency confirms the closure order.")],
        identified: "The patrol officer found {D} with the buckets.",
        notDone: ["The closure notice's posting date was never confirmed.", "The clams were never measured by an independent warden."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let rodeoClownShoveV1 = SmallCases.make(
        key: "story.rodeoClownShove",
        category: .violent,
        headlines: ["Mascot in Costume Shoves Fan Who Dumped Beer on Him at Minor League Game", "Stadium Camera Shows Shove on Concourse Stairs"],
        law: "simpleAssault",
        spec: "Assaulted {V} by shoving {V.him} down a concourse stair, on {DATE}.",
        ages: 20...55,
        victim: true,
        summary: "At a minor league baseball game on {DATE}, {D}, in a mascot costume, walked the concourse during the seventh inning. {V} poured a cup of beer on the costume's head at 8:55 p.m. {D} shoved {V} backward and {V} fell down two steps and bruised a hip. A stadium camera recorded it. {D} says {V} poured the beer first and {D.he} reacted without thinking.",
        state: [E(.video, 3, "Stadium Camera", "{V} pours beer on the costume and {D} shoves {V} backward at 8:55 p.m."), E(.document, 2, "Medical Note", "A bruised hip and a scraped hand."), E(.statement, 2, "Usher", "Saw the beer and the shove."), E(.document, 2, "Team Conduct Policy", "Mascots may not touch fans.")],
        defense: [E(.statement, 1, "Beer First", "{DL} says {V} poured beer first and {D.he} reacted without thinking."), E(.document, 1, "Costume Visibility", "A note that the costume's head limits vision.")],
        role: "Stadium usher",
        exam: [.direct("Tell us about your job at the ballpark.", "\"I work as an usher at the minor league stadium. I show fans to their seats, watch the concourse, and step in when there is a problem in the stands.\""), .direct("What did you see during the seventh inning?", "\"I saw {V} walk up to the mascot on the concourse and pour a cup of beer on the costume's head. It was about 8:55 p.m.\""), .direct("What did the mascot do after the beer was poured?", "\"{D}, in the costume, shoved {V} backward. {V} fell down two steps, and I ran over to help and called for deputies.\""), .direct("What injuries did {V} have?", "\"A bruised hip and a scraped hand. {V} was upset and sore, and I stayed with {V} until help arrived and the stadium staff took a report.\""), .direct("What is the stadium's policy on the mascot touching fans?", "\"Mascots may not touch fans. That rule protects fans and the costume wearer, and everyone who wears the costume is told about it in training.\""), .direct("What does the stadium camera show?", "\"It shows {V} pouring the beer on the costume and {D} shoving {V} backward at 8:55 p.m. The video matches what I saw from where I stood.\""), .cross("Did {V} pour the beer first?", "\"Yes. I saw {V} pour the cup on the costume's head. I do not know why, but it was {V}'s act that started it.\""), .cross("Can the mascot see well through the costume?", "\"Not very well. The head limits vision, and the wearer has to look through a small mesh opening, especially in a crowded concourse.\""), .cross("Did {D} shove {V} more than once?", "\"I saw one shove that sent {V} backward. The camera may show a second push, and I cannot say for certain from where I stood.\""), .cross("Was {D} cooperative afterward?", "\"Yes. {D} took the head off and apologized. {D} stayed until deputies arrived and did not try to leave the stadium.\""), .cross("Was the concourse crowded at that moment?", "\"Yes. It was the seventh inning, and many fans were walking and buying food. The crowd made it hard for anyone to see well.\"")],
        defenseRole: "Concession stand worker",
        defenseExam: [.direct("Tell the jury about your work at the concession stand.", "\"I work a concession stand on that concourse. I serve food and drinks to fans, and I see the mascot walk by every night during the seventh inning.\""), .direct("What did you see of {V} before the beer?", "\"I saw {V} walking toward the mascot holding a cup of beer. I did not think much of it until {V} poured it over the costume's head.\""), .direct("What did {D} do right after the beer was poured?", "\"{D} shoved {V} backward right away. It looked like a quick reaction. {D} did not step toward {V} before the beer hit the costume.\""), .direct("How crowded was the concourse at that time?", "\"Very. The seventh inning always brings a crowd to the concourse, and fans were shoulder to shoulder in front of my stand and the next one.\""), .direct("What did {D} do after the fall?", "\"{D} took off the head and looked horrified. {D} went to help and said sorry, and I could see {D} was upset about what happened.\""), .direct("What is {D} like with fans on the concourse?", "\"Friendly. I have watched {D} pose for photos with kids for a whole season. I never saw {D} lose patience before this night.\""), .cross("Did {V} pour the beer?", "\"Yes. I saw it. {V} poured a cup of beer over the mascot's head, and I do not know why anyone would do that to a person.\""), .cross("Did {D} shove {V} back?", "\"Yes. {D} shoved {V} backward, and I saw {V} stumble. I did not see the second push, but I saw {V} fall down the steps.\""), .cross("Did {V} fall?", "\"Yes. {V} fell down two steps. I did not see how hard, but I saw {V} on the ground afterward, holding a hip.\""), .cross("Did you call anyone for help?", "\"The usher called deputies. I stayed at my stand because the line was long, but I watched the whole thing from there.\""), .cross("Could {D} see {V} coming before the beer hit?", "\"I do not think so. The head limits what {D} can see, and I do not think {D} saw the cup until it was on top of the costume.\"")],
        theory: ("{D} shoved a fan.", "{V} poured beer first."),
        allocution: "\"I hurt someone who didn't deserve it. I'm sorry.\"",
        truths: ("{DL} shoved {V} twice.", "{DL} could not see well and reacted to the beer."),
        defendant: [.direct("What can you tell us about your work as the mascot?", "\"I wear the costume at home games and walk the concourse to greet fans and pose for photos. It is hot work, and I love it.\""), .direct("What happened when {V} approached?", "\"{V} came up and poured a cup of beer on the head of the costume. It was cold and sticky, and it hit me by surprise.\""), .direct("Why did you shove {V}?", "\"I could not see well and I reacted without thinking. I pushed {V} away to get {V} off me, and I did not mean to hurt anyone.\""), .direct("How well can you see in the costume?", "\"Barely. The mesh is small and the head blocks most of my side view. In a crowd, I mostly see shapes and the people directly in front.\""), .direct("What did you do after you realized {V} fell?", "\"I took off the head and went to help. I told {V} I was sorry, and I stayed until deputies arrived and the usher took over.\""), .direct("How do you feel about what happened?", "\"I would say I feel awful. I know I am not supposed to touch fans, and I never wanted anyone to be hurt. I would take that moment back.\""), .cross("You shoved {V} backward, didn't you?", "\"Yes. I pushed {V} away, and {V} went backward down two steps. I did not mean for {V} to fall, but I know what I did.\""), .cross("The team policy says mascots may not touch fans, doesn't it?", "\"Yes. I know the rule, and I forgot it in that moment. I reacted to the beer and not to what the policy says.\""), .cross("You shoved {V} twice, didn't you?", "\"The video shows two pushes. I do not remember them clearly. I know the second one was not needed once the first one had worked.\""), .cross("{V} fell and was hurt, wasn't {V}?", "\"Yes. {V} fell down two steps and bruised a hip. I did not mean it, but I understand {V} was hurt because of what I did.\""), .cross("You could have walked away, couldn't you?", "\"Yes. I could have, and I should have. I reacted too fast, and I know that is part of why this is in court.\"")],
        openings: ("During the seventh inning at a minor league game, {D}, in a mascot costume, shoved a fan backward down two steps. The fan, {V}, suffered a bruised hip and a scraped hand, and a stadium camera recorded the shove.", "The defense will explain that {V} poured a cup of beer on the mascot's head first, that the costume limits vision, and that {D} reacted without thinking. A reflex in a crowded concourse is not a plan to hurt anyone."),
        closings: ("A shove on the concourse during the seventh inning, a fan who fell down two steps, a bruised hip, and a team rule that says mascots may not touch fans. The camera recorded two pushes.", "A cup of beer on a costume and a reaction that came before any thought. The State has not proved that {D} meant to hurt {V}, and a person who cannot see well reacts to what hits them."),
        timeline: [(0, "8:55 p.m.: {V} pours beer on the costume."), (0, "8:55 p.m.: {D} shoves {V}."), (0, "9:05 p.m.: an usher calls deputies."), (1, "The stadium sends the camera video.")],
        identified: "The stadium camera identifies {D}.",
        notDone: ["The costume's padding was never checked for a push.", "The concession's cup was never traced."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let plowChaseLotV1 = SmallCases.make(
        key: "story.plowChaseLot",
        category: .traffic,
        headlines: ["Loader Tractor Chases Pickup Through Feed Store Lot After Argument Over Pallet", "Feed Store Camera Shows Bucket Raised Behind Fleeing Truck"],
        law: "recklessDriving",
        spec: "Drove carelessly and heedlessly in willful disregard of the rights of others, chasing a pickup through a lot with a loader tractor, on {DATE}.",
        ages: 21...65,
        victim: false,
        summary: "At 3 p.m. on {DATE}, {D} drove a loader tractor with the bucket raised after a pickup through a feed store lot following a dispute over a pallet of feed. The pickup swerved through the lot and clipped a post. A deputy arrived at 3:12 p.m. and found {D} still in the lot. The pickup's mirror was broken. {D} says the pickup tried to run {D.him} down.",
        state: [E(.video, 3, "Feed Store Camera", "{D}'s loader chases the pickup across the lot with the bucket raised."), E(.document, 2, "Repair Estimate", "A broken mirror and a dented fender on the pickup."), E(.statement, 2, "Pickup Driver", "Swerved when the loader came up behind the truck."), E(.document, 2, "Deputy's Report", "Found the loader running in the lot at 3:12 p.m.")],
        defense: [E(.statement, 1, "Almost Run Down", "{DL} says the pickup tried to run {D.him} down."), E(.document, 1, "Photo", "A photo of tire marks near the pallet.")],
        role: "Sheriff's deputy",
        exam: [.direct("What are your duties as a sheriff's deputy?", "\"I patrol the county and respond to disturbances, crashes, and fights. I take statements, collect video, and write reports when a vehicle or equipment is involved.\""), .direct("What did you find when you arrived at the feed store?", "\"At 3:12 p.m. I found {D} still in the lot with the loader running. A pickup was nearby with a broken mirror and a dented fender.\""), .direct("What did the feed store camera show?", "\"It shows {D}'s loader chasing the pickup across the lot with the bucket raised. The pickup swerves, and the video ends with it clipping a post.\""), .direct("What damage did the pickup have?", "\"A broken mirror and a dented fender. The repair estimate covers both. The mirror broke against a post, according to the pickup's driver.\""), .direct("What was the argument about?", "\"A pallet of feed. {D} and the pickup driver argued about it around three o'clock, and the loader started moving at about five minutes after.\""), .direct("What did you observe about the loader?", "\"It was running when I arrived, with the bucket raised. I photographed it and checked the tracks near the pallet, and I took a statement from {D}.\""), .cross("Did the pickup swerve toward the pallet first?", "\"I am told it did. A photo of tire marks near the pallet shows the pickup moved sharply there, and I cannot say who started the movement.\""), .cross("Did anyone get hurt?", "\"No. No one was injured. The pickup clipped a post and stopped, and nobody was struck by either vehicle.\""), .cross("Did {D} threaten the pickup driver?", "\"The driver says {D} did after the argument. I did not hear it myself, and I have only the driver's account.\""), .cross("Did {D} stay at the scene?", "\"Yes. {D} was still in the lot when I arrived, and {D} did not try to leave. {D} cooperated and answered my questions.\""), .cross("Did you call anyone else to the scene?", "\"I called for a second deputy to take photos and measurements. We did not need medical help, and we did not need to close the lot.\"")],
        defenseRole: "Store employee",
        defenseExam: [.direct("Please describe your job at the feed store.", "\"I work the counter and help customers load. I know the loader driver and the usual customers, and I was in the lot that afternoon when the argument began.\""), .direct("What was the dispute about?", "\"A pallet of feed. {D} and the pickup driver disagreed about who the pallet was for. They argued loudly, and I stepped back so I would not get involved.\""), .direct("What did you see {D} do with the loader?", "\"{D} raised the bucket and drove after the pickup. It looked like {D} was trying to block it, and I did not see {D} hit anything.\""), .direct("What did the pickup do before {D} started the loader?", "\"It swerved toward the pallet and toward {D}. I saw the tires cut sharply, and I thought for a second that someone might get hit.\""), .direct("What happened when the pickup reached the post?", "\"It clipped the post and stopped. I saw the mirror break. I did not see the loader touch the pickup at any point.\""), .direct("What did {D} do afterward?", "\"{D} stopped the loader and stayed in the lot. {D} was shaken and said the pickup tried to run {D} down, and waited for the deputy.\""), .cross("Did {D} raise the bucket?", "\"Yes. {D} raised the bucket as the loader moved. I cannot say whether it was to block the truck or for another reason.\""), .cross("Did the pickup stop quickly?", "\"Eventually. It took a few seconds after the post. The driver sat in the truck until the deputy arrived, and I did not talk to the driver.\""), .cross("Did anyone get hurt?", "\"No. Nobody was hurt. It could have been worse if the pickup had hit someone, but both vehicles stopped before that happened.\""), .cross("Did {D} say anything to threaten the driver?", "\"I heard shouting from both. I did not hear every word. I cannot say whether {D} made a threat during the argument.\""), .cross("Did you see the tire marks near the pallet?", "\"Yes. There were marks that showed the pickup turned sharply near the pallet. I did not measure them, and I do not know how fast it was going.\"")],
        theory: ("{D} chased a pickup with a loader.", "The pickup tried to run {D} down."),
        allocution: "\"I put people in danger and I'm sorry.\"",
        truths: ("{DL} had threatened the pickup driver after the dispute.", "The pickup did swerve toward the pallet first."),
        defendant: [.direct("Tell us about your work at the feed store.", "\"I drive the loader at the feed store. I move pallets and load trucks all day, and I have operated the machine for years.\""), .direct("What was the argument with the pickup driver about?", "\"A pallet of feed. I thought it was mine to load, and the driver thought it was for the pickup. We argued, and it got heated.\""), .direct("Why did you start the loader after the pickup?", "\"The pickup came at me. I was by the pallet, and the driver swerved toward me. I started the loader to protect myself and the pallet.\""), .direct("Why was the bucket raised?", "\"I raised it to block the pickup and keep it from coming at me again. I did not want to hit anyone or anything.\""), .direct("What happened when the pickup clipped the post?", "\"The mirror broke on the post, not on the loader. I did not touch the pickup. I stopped the loader and waited for the deputy.\""), .direct("What did you do after that?", "\"I stayed in the lot. I did not call the deputies myself, but I did not run, and I told the deputy exactly what happened.\""), .cross("The bucket was raised during the chase, wasn't it?", "\"Yes. I raised it to block the pickup. I understand it looks like a chase on the video, but I was not trying to hit the truck.\""), .cross("You told the pickup driver you would get even, didn't you?", "\"I said something angry after the dispute. I did not mean it as a threat, and I did not plan to use the loader on anyone.\""), .cross("The mirror was broken, wasn't it?", "\"Yes. It broke on a post. The loader never touched it, and I stopped before I got close to the pickup.\""), .cross("You did not call deputies, did you?", "\"No. I did not. I should have called as soon as the pickup came at me, and I did not think of it in the moment.\""), .cross("You chased the pickup across the lot, didn't you?", "\"The video shows the loader moving after the pickup. I moved to protect myself, and I know how it looks on camera.\"")],
        openings: ("At 3 p.m. on {DATE}, {D} drove a loader tractor with the bucket raised after a pickup through a feed store lot following a dispute over a pallet. The pickup swerved and clipped a post, and a deputy found {D} still in the lot.", "The defense will present a pickup that swerved toward a worker first, tire marks near the pallet, and a loader driver who raised a bucket to block it. Protecting yourself is not a chase."),
        closings: ("A loader with the bucket raised chasing a pickup across a feed store lot, a broken mirror, a dented fender, and a driver who says {D} came up behind the truck. The camera shows the chase.", "A pickup swerving toward a worker and a loader bucket raised to block it. A dispute over a pallet can end with a pickup running, and the State has not proved {D} chased anyone."),
        timeline: [(0, "3 p.m.: the argument over the pallet."), (0, "3:05 p.m.: {D} starts the loader."), (0, "3:12 p.m.: the deputy arrives."), (1, "The store sends its camera video.")],
        identified: "The store camera identifies {D}.",
        notDone: ["The pallet's ownership was never resolved.", "The tractor's bucket height was never measured."],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let pranksterBalloonCallV1 = SmallCases.make(
        key: "story.pranksterBalloonCall",
        category: .publicOrder,
        headlines: ["Man Calls In Person Drowning in Pond for 'Rescue Drill' Video", "Dive Team Search Turns Up Empty Pond and a Camera"],
        law: "falseReport",
        spec: "Made a false report to a law enforcement agency that a person was drowning in a pond, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "At 5:10 p.m. on {DATE}, {D} called 911 and said a person was drowning in a town pond. Fire and rescue crews and a dive team searched the pond for forty minutes. No one was in the water. A camera on a tripod on the far shore recorded the crews' arrival. {D} says {D.he} wanted to see how fast crews arrived for a project.",
        state: [E(.digital, 3, "911 Recording", "{D} reports a person drowning at the town pond at 5:11 p.m."), E(.document, 3, "Rescue Log", "Two engines and a dive team searched the pond from 5:20 to 6 p.m."), E(.video, 2, "Tripod Camera", "A camera on the far shore records the crews' arrival."), E(.document, 2, "Phone Records", "The call came from a phone registered to {D}.")],
        defense: [E(.statement, 1, "Response Time Project", "{DL} says {D.he} wanted to see how fast crews arrived for a class project."), E(.document, 1, "Class Assignment", "A description of a project on 'municipal response times.'")],
        role: "911 dispatcher",
        exam: [.direct("What are your duties as a 911 dispatcher?", "\"I answer emergency calls and send fire, rescue, and sheriff's crews. I stay on the line with callers, take notes, and record every call and its time.\""), .direct("What did the caller say at 5:11 p.m. on {DATE}?", "\"The caller said a person was drowning in the town pond. The caller was calm, gave the location, and asked for help right away.\""), .direct("What did you do after the call?", "\"I dispatched two engines and a dive team. The crews arrived at about 5:20 and searched the pond until about six.\""), .direct("What did the crews find?", "\"No one was in the water. The search took forty minutes, and crews used boats and divers to check the pond, which cost the town resources.\""), .direct("How was the caller identified?", "\"The phone records show the call came from a phone registered to {D}. The recording matches the voice, and a tripod camera on the far shore also recorded the crews.\""), .direct("What does a false drowning call do to other emergencies?", "\"It ties up engines and divers. If a real emergency had happened during those forty minutes, crews would have been farther away and slower to respond.\""), .cross("Did {D} say it was a class project?", "\"Later, yes. {D} said it was for a class project on municipal response times. I did not hear that during the call.\""), .cross("Did {D} tell you it was a test during the call?", "\"No. {D} did not say it was a test. The call was made as if a real person was drowning, and I took it seriously.\""), .cross("Did {D} try to cancel the call?", "\"No. {D} did not call back to cancel it. The crews searched for forty minutes with no word that it was a test.\""), .cross("Was anyone in the water when crews arrived?", "\"No. No one was in the water, and nobody was hurt. The crews were relieved, though some were frustrated by the false alarm.\""), .cross("Did the crews arrive quickly?", "\"Yes. They arrived at about 5:20, nine minutes after the call. That is a fast response, and it was exactly what a real emergency would need.\"")],
        defenseRole: "Video partner",
        defenseExam: [.direct("Describe your work with {D} on the video for the jury.", "\"I am a partner on the project. I help with filming and editing, and I was with {D} when we set up the camera on the far shore.\""), .direct("What was the plan for the video?", "\"The plan was to record how fast crews arrived at the pond. {D} wanted a time stamp from the call to the first engine, and I agreed.\""), .direct("What did {D} tell you before the call?", "\"{D} said it would be a quick test and that nobody would be hurt. I did not know {D} would claim a drowning, and I wish I had asked.\""), .direct("What did you see when the crews arrived?", "\"Two engines and a dive team came fast. They searched the pond for forty minutes, and I realized it was bigger than we had planned.\""), .direct("How did {D} react to the response?", "\"{D} was shocked. {D} said it was too much and that {D} should have thought it through. {D} looked sick as the divers went in.\""), .direct("What kind of person is {D}?", "\"Serious about school and polite. {D} has never been in trouble that I know of, and this was a bad idea that grew out of an assignment.\""), .cross("Did {D} call 911?", "\"Yes. I saw {D} make the call. I was standing next to {D}, and I did not stop it, and I know I own that.\""), .cross("Did you warn the town about the drill?", "\"No. We did not warn anyone. I do not know how we would have done it, and I did not think about it at the time.\""), .cross("Did crews arrive fast?", "\"Yes. They arrived in about nine minutes. It was impressive, and it also made me realize how real the call had sounded.\""), .cross("Did you try to stop the search?", "\"No. I did not know how. We did not want to admit what we had done while the crews were searching, and I regret that.\""), .cross("Did anyone tell you it was legal to make a test call?", "\"No. No one said that. We assumed it was harmless, and nobody checked. I know now that a false report is a crime.\"")],
        theory: ("{D} called in a drowning that did not exist.", "{D} tested response times for a project."),
        allocution: "\"I was angry and I made it everyone else's problem.\"",
        truths: ("{DL} had planned the call and set up the camera in advance.", "{DL} thought a test call was harmless."),
        defendant: [.direct("Please tell us about your class project.", "\"I was assigned a project on municipal response times. I wanted to see how fast crews would arrive, and I planned to record it on a camera.\""), .direct("How did you plan the project?", "\"I set up a tripod camera on the far shore a few minutes before the call. I planned to call 911 and time the arrival of the crews.\""), .direct("Why did you call 911?", "\"I thought a test call would be harmless and would help with my project. I did not think about how many crews would respond or how long they would stay.\""), .direct("What did you say on the call?", "\"I said a person was drowning at the pond. I wanted it to sound real so that the response would be real, and that was a mistake.\""), .direct("Why did you not cancel the call?", "\"I did not think about it until it was too late. I watched the crews arrive, and I was shocked at how many came.\""), .direct("Looking back, how do you feel about what happened?", "\"Mostly I feel terrible. I took a project too far, and I wasted the time of people who save lives. I am sorry to the crews and the town.\""), .cross("You called 911 to report a drowning that did not exist, didn't you?", "\"Yes. I did. I know it was wrong. There was no one in the water, and I wanted to see how fast the crews would arrive.\""), .cross("You set up a camera before you called, didn't you?", "\"Yes. I set it up at about 5:05 to record the crews. I planned the whole thing in advance, and I know that makes it look worse.\""), .cross("You did not warn the town or the dispatchers, did you?", "\"No. I did not warn anyone. If I had warned them, it would not have been a real test, and I now see that was the problem.\""), .cross("The crews searched for forty minutes, didn't they?", "\"Yes. They searched until about six. I watched them with the camera, and I did not stop it, even though I could have.\""), .cross("You thought a test call was harmless, didn't you?", "\"Yes. I did, and I was wrong. I did not think about the cost to the town or about a real emergency that could have happened.\"")],
        openings: ("At 5:10 on a night in {DATE}, {D} called 911 and said a person was drowning in a town pond. Two engines and a dive team searched for forty minutes, and no one was in the water.", "The defense will present a class assignment on municipal response times and a student who thought a test call would be harmless. A bad idea at school is not an intent to cause harm."),
        closings: ("A false drowning report, a forty-minute search, two engines and a dive team tied up, and a camera set up in advance to record the crews. The call was planned, and the crews took it seriously.", "A class project and a test call that seemed harmless. A rescue drill video is not a reason to call 911, but the State must prove that {D} meant to cause a false alarm."),
        timeline: [(0, "5:05 p.m.: {D} sets up the camera."), (0, "5:10 p.m.: {D} calls 911."), (0, "5:20 p.m.: crews arrive."), (0, "6 p.m.: the search ends.")],
        identified: "The 911 recording is {D}'s voice.",
        notDone: ["The video's script was never read.", "The dive team's cost was never itemized."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])
}
